import 'dart:math';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:shared_preferences/shared_preferences.dart';

import '../utils/constants.dart';
import '../widgets/virtual_joystick_widget.dart';
import '../widgets/online_players_panel.dart';

// ============================================================
// SHARED CONSTANTS & HELPERS
// ============================================================
const Color kNeonRed    = Color(0xFFFF2244);
const Color kNeonCyan   = Color(0xFF00FFFF);
const Color kNeonMagenta= Color(0xFFFF00CC);
const Color kNeonOrange = Color(0xFFFF8800);
const Color kNeonYellow = Color(0xFFFFEE00);
const Color kNeonGold   = Color(0xFFFFD700);
const Color kNeonLime   = Color(0xFF88FF00);
const Color kDarkBg     = Color(0xFF03040E);

// ============================================================
// DATA MODELS — WARZONE BLITZ
// ============================================================
enum WzWeaponType {
  pistol, smg, assaultRifle, shotgun, sniperRifle,
  hmg, grenadeLauncher, plasmaCannon, laserBeam, railgun
}

class WzWeapon {
  final WzWeaponType type;
  final String name;
  final int maxAmmo;
  final int clipSize;
  final double fireRate;      // shots per second
  final double damage;
  final double reloadTime;    // seconds
  final double spreadRadius;  // crosshair hit radius multiplier
  final Color bulletColor;
  int ammo;
  int totalAmmo;
  bool isReloading = false;
  double reloadProgress = 0;
  double fireCooldown = 0;

  WzWeapon({
    required this.type,
    required this.name,
    required this.maxAmmo,
    required this.clipSize,
    required this.fireRate,
    required this.damage,
    required this.reloadTime,
    required this.spreadRadius,
    required this.bulletColor,
  })  : ammo = clipSize,
        totalAmmo = maxAmmo;

  static WzWeapon pistol() => WzWeapon(
    type: WzWeaponType.pistol, name: 'PISTOL', maxAmmo: 60, clipSize: 12,
    fireRate: 3.0, damage: 25, reloadTime: 1.0, spreadRadius: 0.06, bulletColor: Colors.white,
  );
  static WzWeapon smg() => WzWeapon(
    type: WzWeaponType.smg, name: 'SMG', maxAmmo: 120, clipSize: 30,
    fireRate: 10.0, damage: 15, reloadTime: 1.5, spreadRadius: 0.08, bulletColor: kNeonLime,
  );
  static WzWeapon assaultRifle() => WzWeapon(
    type: WzWeaponType.assaultRifle, name: 'ASSAULT RIFLE', maxAmmo: 90, clipSize: 30,
    fireRate: 6.0, damage: 30, reloadTime: 2.0, spreadRadius: 0.05, bulletColor: kNeonYellow,
  );
  static WzWeapon shotgun() => WzWeapon(
    type: WzWeaponType.shotgun, name: 'SHOTGUN', maxAmmo: 32, clipSize: 8,
    fireRate: 1.5, damage: 80, reloadTime: 2.5, spreadRadius: 0.15, bulletColor: kNeonOrange,
  );
  static WzWeapon sniperRifle() => WzWeapon(
    type: WzWeaponType.sniperRifle, name: 'SNIPER', maxAmmo: 20, clipSize: 5,
    fireRate: 0.8, damage: 120, reloadTime: 3.0, spreadRadius: 0.025, bulletColor: Colors.lightBlue,
  );
  static WzWeapon hmg() => WzWeapon(
    type: WzWeaponType.hmg, name: 'HMG', maxAmmo: 200, clipSize: 50,
    fireRate: 15.0, damage: 20, reloadTime: 4.0, spreadRadius: 0.12, bulletColor: kNeonRed,
  );
  static WzWeapon grenadeLauncher() => WzWeapon(
    type: WzWeaponType.grenadeLauncher, name: 'GRENADE LAUNCHER', maxAmmo: 12, clipSize: 3,
    fireRate: 0.5, damage: 200, reloadTime: 2.5, spreadRadius: 0.3, bulletColor: kNeonOrange,
  );
  static WzWeapon plasmaCannon() => WzWeapon(
    type: WzWeaponType.plasmaCannon, name: 'PLASMA CANNON', maxAmmo: 30, clipSize: 6,
    fireRate: 1.0, damage: 150, reloadTime: 3.0, spreadRadius: 0.06, bulletColor: kNeonPurple,
  );
  static WzWeapon laserBeam() => WzWeapon(
    type: WzWeaponType.laserBeam, name: 'LASER BEAM', maxAmmo: 50, clipSize: 10,
    fireRate: 2.0, damage: 60, reloadTime: 2.0, spreadRadius: 0.02, bulletColor: kNeonCyan,
  );
  static WzWeapon railgun() => WzWeapon(
    type: WzWeaponType.railgun, name: 'RAILGUN', maxAmmo: 10, clipSize: 2,
    fireRate: 0.3, damage: 500, reloadTime: 5.0, spreadRadius: 0.01, bulletColor: Colors.white,
  );

  static List<WzWeapon> all() => [
    pistol(), smg(), assaultRifle(), shotgun(), sniperRifle(),
    hmg(), grenadeLauncher(), plasmaCannon(), laserBeam(), railgun(),
  ];
}

class WzEnemy {
  double x, depth, speed;
  int type, hp, maxHp;
  bool isDying = false;
  double dieTimer = 0;
  WzEnemy({required this.x, required this.depth, required this.type, required this.hp, required this.speed})
      : maxHp = hp;
}

class WzParticle {
  double x, y, vx, vy, life, maxLife, size;
  Color color;
  WzParticle({required this.x, required this.y, required this.vx, required this.vy,
    required this.life, required this.color, this.size = 3})
      : maxLife = life;
}

class WzBulletTrail {
  double x1, y1, x2, y2, life;
  Color color;
  WzBulletTrail({required this.x1, required this.y1, required this.x2, required this.y2,
    required this.life, required this.color});
}

class WzDialogue {
  final String speaker;
  final String message;
  final Color speakerColor;
  final List<String>? choices;
  const WzDialogue({required this.speaker, required this.message, required this.speakerColor, this.choices});
}

// ============================================================
// WARZONE BLITZ GAME
// ============================================================
class WarzoneBlitzGame extends StatefulWidget {
  const WarzoneBlitzGame({Key? key}) : super(key: key);
  @override
  State<WarzoneBlitzGame> createState() => _WarzoneBlitzGameState();
}

class _WarzoneBlitzGameState extends State<WarzoneBlitzGame> with TickerProviderStateMixin {
  late AnimationController _gameLoop;

  // State
  bool _isPlaying = false;
  bool _isGameOver = false;
  bool _showDialogue = false;
  bool _showShop = false;
  bool _isBetweenWaves = false;
  String _difficulty = 'Medium';

  // Stats
  double _health = 100;
  double _maxHealth = 100;
  double _armor = 0;
  int _score = 0;
  int _highScore = 0;
  int _wave = 1;
  int _kills = 0;
  int _grenades = 3;
  int _coins = 0;
  int _comboKills = 0;
  double _comboTimer = 0;

  // Weapon
  List<WzWeapon> _weapons = [];
  int _currentWeaponIdx = 0;
  WzWeapon get _currentWeapon => _weapons[_currentWeaponIdx];

  // Perks
  bool _perkDoubleTap = false;
  bool _perkSpeedBoost = false;
  bool _perkArmorPlating = false;
  int _perkDoubleTapCost = 200;
  int _perkSpeedBoostCost = 150;
  int _perkArmorPlatingCost = 300;
  int _weaponUpgradeCost = 100;

  // Movement / Aiming
  Offset _crosshairPos = const Offset(0.5, 0.45);
  double _playerStrafe = 0.5;
  double _moveSpeed = 0.025;

  // Game Objects
  final List<WzEnemy> _enemies = [];
  final List<WzParticle> _particles = [];
  final List<WzBulletTrail> _bulletTrails = [];

  // Spawn
  final Random _rnd = Random();
  double _spawnTimer = 0;
  int _enemiesToSpawn = 0;
  double _betweenWaveTimer = 0;

  // Visual FX
  double _damageFlash = 0;
  double _screenShake = 0;
  bool _isFiring = false;
  double _fireTimer = 0;

  // Dialogue
  List<WzDialogue> _dialogueQueue = [];
  WzDialogue? _currentDialogue;

  // Campaign story
  final List<List<WzDialogue>> _waveDialogues = const [
    [ // Before wave 1
      WzDialogue(speaker: 'GENERAL BRIGGS', message: 'Commander Vance! The Cyber-Grip Faction has breached the perimeter. Defend your position!', speakerColor: Color(0xFF4FC3F7)),
      WzDialogue(speaker: 'PILOT LUNA', message: 'Striker, I\'m picking up 5 hostiles inbound. First wave incoming!', speakerColor: Color(0xFF80CBC4)),
      WzDialogue(speaker: 'STRIKER', message: 'Copy that. I\'ll hold the line. Opening fire!', speakerColor: kNeonGreen,
        choices: ['Request Air Support', 'Request Ammo Drop', 'Hold Position']),
    ],
    [ // Before wave 2
      WzDialogue(speaker: 'PILOT LUNA', message: 'Wave 2! They\'re sending armor support. Watch out for tanks!', speakerColor: Color(0xFF80CBC4)),
      WzDialogue(speaker: 'STRIKER', message: 'Switching to anti-armor rounds. Bring it on!', speakerColor: kNeonGreen),
    ],
    [ // Before wave 3
      WzDialogue(speaker: 'GENERAL BRIGGS', message: 'Enemy snipers spotted on the ridge! Keep moving, Vance!', speakerColor: Color(0xFF4FC3F7)),
      WzDialogue(speaker: 'STRIKER', message: 'I see them. Flanking left!', speakerColor: kNeonGreen,
        choices: ['Use Plasma Cannon', 'Use Grenade', 'Dodge Left']),
    ],
    [ // Before wave 4
      WzDialogue(speaker: 'PILOT LUNA', message: 'Striker! Aegis-7 just bombed Sector C. We\'re cut off from backup!', speakerColor: Color(0xFF80CBC4)),
      WzDialogue(speaker: 'STRIKER', message: 'Then it\'s just us. Open the armory — I need everything!', speakerColor: kNeonGreen),
    ],
    [ // Before wave 5
      WzDialogue(speaker: 'GENERAL BRIGGS', message: 'Command has been lost. Hold Nexdroid Central at ALL costs, Commander!', speakerColor: Color(0xFF4FC3F7)),
      WzDialogue(speaker: 'STRIKER', message: 'Nexdroid will not fall. Operation Neon Storm — FINAL STAND!', speakerColor: kNeonGreen,
        choices: ['Nuke Strike', 'Air Assault', 'Full Defense']),
    ],
  ];

  @override
  void initState() {
    super.initState();
    _loadHighScore();
    _gameLoop = AnimationController(vsync: this, duration: const Duration(seconds: 1))..repeat();
    _gameLoop.addListener(_update);
  }

  Future<void> _loadHighScore() async {
    final prefs = await SharedPreferences.getInstance();
    setState(() => _highScore = prefs.getInt('hi_score_warzone_blitz') ?? 0);
  }

  Future<void> _saveHighScore() async {
    if (_score > _highScore) {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setInt('hi_score_warzone_blitz', _score);
      _highScore = _score;
    }
  }

  void _startGame(String diff) {
    _difficulty = diff;
    _weapons = WzWeapon.all();
    _currentWeaponIdx = 2; // Start with Assault Rifle
    setState(() {
      _isPlaying = true;
      _isGameOver = false;
      _showShop = false;
      _showDialogue = false;
      _isBetweenWaves = false;
      _health = 100;
      _maxHealth = 100;
      _armor = 0;
      _score = 0;
      _wave = 1;
      _kills = 0;
      _grenades = 3;
      _coins = 0;
      _comboKills = 0;
      _comboTimer = 0;
      _perkDoubleTap = false;
      _perkSpeedBoost = false;
      _perkArmorPlating = false;
      _enemies.clear();
      _particles.clear();
      _bulletTrails.clear();
      _crosshairPos = const Offset(0.5, 0.45);
      _playerStrafe = 0.5;
      _damageFlash = 0;
      _screenShake = 0;
      _enemiesToSpawn = 5 + _wave * 2;
      _spawnTimer = 0;
    });
    // Trigger pre-wave dialogue
    if (_wave <= _waveDialogues.length) {
      _startDialogue(_waveDialogues[_wave - 1]);
    }
    HapticFeedback.mediumImpact();
  }

  void _startDialogue(List<WzDialogue> dialogues) {
    _dialogueQueue = List.from(dialogues);
    _showDialogue = true;
    _currentDialogue = _dialogueQueue.isNotEmpty ? _dialogueQueue.removeAt(0) : null;
    setState(() {});
  }

  void _advanceDialogue(int choiceIdx) {
    if (_currentDialogue?.choices != null && choiceIdx >= 0) {
      _applyDialogueChoice(_currentDialogue!.choices![choiceIdx]);
    }
    if (_dialogueQueue.isEmpty) {
      _showDialogue = false;
      _currentDialogue = null;
    } else {
      _currentDialogue = _dialogueQueue.removeAt(0);
    }
    setState(() {});
  }

  void _applyDialogueChoice(String choice) {
    switch (choice) {
      case 'Request Air Support':
        _enemies.clear();
        _score += 500;
        _spawnExplosions(0.5, 0.4, 20);
        break;
      case 'Request Ammo Drop':
        for (var w in _weapons) {
          w.ammo = w.clipSize;
          w.totalAmmo = w.maxAmmo;
        }
        break;
      case 'Hold Position':
        _health = _maxHealth;
        break;
      case 'Use Plasma Cannon':
        _currentWeaponIdx = _weapons.indexWhere((w) => w.type == WzWeaponType.plasmaCannon);
        break;
      case 'Use Grenade':
        _throwGrenade();
        break;
      case 'Dodge Left':
        _playerStrafe = 0.1;
        break;
      case 'Nuke Strike':
        _spawnExplosions(0.5, 0.5, 50);
        final toRemove = List.from(_enemies);
        for (var _ in toRemove) {
          _score += 200;
          _kills++;
        }
        _enemies.clear();
        break;
      case 'Air Assault':
        for (int i = 0; i < 10; i++) {
          _spawnExplosions(_rnd.nextDouble(), _rnd.nextDouble() * 0.5 + 0.1, 5);
        }
        _enemies.clear();
        break;
      case 'Full Defense':
        _armor = 50;
        _health = _maxHealth;
        break;
    }
  }

  void _update() {
    if (!_isPlaying || _isGameOver || _showDialogue || _showShop) return;
    const double dt = 1 / 60;

    // Fade FX
    if (_damageFlash > 0) _damageFlash = (_damageFlash - dt * 2).clamp(0, 1);
    if (_screenShake > 0) _screenShake = (_screenShake - dt * 5).clamp(0, 1);

    // Combo decay
    if (_comboTimer > 0) {
      _comboTimer -= dt;
      if (_comboTimer <= 0) _comboKills = 0;
    }

    // Weapon fire rate
    if (_fireTimer > 0) _fireTimer -= dt;
    if (_currentWeapon.fireCooldown > 0) _currentWeapon.fireCooldown -= dt;

    // Auto-fire if holding fire button
    if (_isFiring && !_currentWeapon.isReloading && _currentWeapon.ammo > 0 &&
        _currentWeapon.fireCooldown <= 0 &&
        _currentWeapon.type != WzWeaponType.sniperRifle &&
        _currentWeapon.type != WzWeaponType.railgun) {
      _fire();
    }

    // Reload
    if (_currentWeapon.isReloading) {
      _currentWeapon.reloadProgress += dt / _currentWeapon.reloadTime;
      if (_currentWeapon.reloadProgress >= 1.0) {
        int need = _currentWeapon.clipSize - _currentWeapon.ammo;
        int from = _currentWeapon.totalAmmo >= need ? need : _currentWeapon.totalAmmo;
        _currentWeapon.ammo += from;
        _currentWeapon.totalAmmo -= from;
        _currentWeapon.isReloading = false;
        _currentWeapon.reloadProgress = 0;
      }
    }

    // Between waves
    if (_isBetweenWaves) {
      _betweenWaveTimer -= dt;
      if (_betweenWaveTimer <= 0) {
        _isBetweenWaves = false;
        _wave++;
        _enemiesToSpawn = 5 + _wave * 3;
        _spawnTimer = 0;
        _health = (_health + 20).clamp(0, _maxHealth);
        _grenades = (_grenades + 1).clamp(0, 5);
        _coins += 100 + _wave * 10;
        // Trigger story dialogue every wave
        if (_wave <= _waveDialogues.length) {
          _startDialogue(_waveDialogues[_wave - 1]);
        } else {
          _showShop = true; // Show shop between waves
        }
        setState(() {});
      }
      return;
    }

    // Spawn enemies
    if (_enemiesToSpawn > 0) {
      _spawnTimer += dt;
      double interval = (1.5 - (_wave * 0.05)).clamp(0.3, 1.5);
      if (_spawnTimer >= interval) {
        _spawnEnemy();
        _spawnTimer = 0;
        _enemiesToSpawn--;
      }
    }

    // Wave complete
    if (_enemiesToSpawn == 0 && _enemies.isEmpty) {
      _isBetweenWaves = true;
      _betweenWaveTimer = 2.0;
    }

    // Move enemies
    for (int i = _enemies.length - 1; i >= 0; i--) {
      var e = _enemies[i];
      if (e.isDying) {
        e.dieTimer -= dt;
        if (e.dieTimer <= 0) _enemies.removeAt(i);
        continue;
      }
      e.depth += e.speed * dt;
      if (e.depth >= 1.0) {
        _enemies.removeAt(i);
        _takeDamage(e.type == 1 ? 30 : e.type == 2 ? 15 : 20);
      }
    }

    // Move particles
    for (int i = _particles.length - 1; i >= 0; i--) {
      var p = _particles[i];
      p.life -= dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vy += 0.5 * dt; // gravity
      if (p.life <= 0) _particles.removeAt(i);
    }

    // Fade bullet trails
    for (int i = _bulletTrails.length - 1; i >= 0; i--) {
      _bulletTrails[i].life -= dt * 8;
      if (_bulletTrails[i].life <= 0) _bulletTrails.removeAt(i);
    }

    setState(() {});
  }

  void _spawnEnemy() {
    double typeRand = _rnd.nextDouble();
    int type = 0;
    if (_wave > 2 && typeRand > 0.75) type = 1; // Tank
    if (_wave > 4 && typeRand > 0.90) type = 2; // Sniper
    double spd = type == 0
        ? 0.12 + (_wave * 0.008) + (_perkSpeedBoost ? 0 : 0)
        : type == 1 ? 0.06 + (_wave * 0.004)
        : 0.09 + (_wave * 0.006);
    if (_difficulty == 'Easy') spd *= 0.7;
    if (_difficulty == 'Hard') spd *= 1.4;
    _enemies.add(WzEnemy(
      x: _rnd.nextDouble() * 0.75 + 0.12,
      depth: 0.0,
      type: type,
      hp: type == 0 ? 1 : type == 1 ? 4 : 2,
      speed: spd,
    ));
  }

  void _takeDamage(double amt) {
    if (_perkArmorPlating) amt *= 0.7;
    if (_armor > 0) {
      double absorbed = amt > _armor ? _armor : amt;
      _armor -= absorbed;
      amt -= absorbed;
    }
    if (_difficulty == 'Hard') amt *= 1.4;
    if (_difficulty == 'Easy') amt *= 0.6;
    _health -= amt;
    _damageFlash = 1.0;
    _screenShake = 1.0;
    HapticFeedback.heavyImpact();
    if (_health <= 0) {
      _health = 0;
      _gameOver();
    }
    setState(() {});
  }

  void _gameOver() {
    _isGameOver = true;
    _isPlaying = false;
    _saveHighScore();
    setState(() {});
  }

  void _fire() {
    if (_currentWeapon.isReloading || _currentWeapon.ammo <= 0) {
      if (_currentWeapon.ammo <= 0 && !_currentWeapon.isReloading) _reload();
      return;
    }
    _currentWeapon.ammo--;
    _currentWeapon.fireCooldown = 1.0 / _currentWeapon.fireRate;
    if (_perkDoubleTap) _currentWeapon.fireCooldown *= 0.6;
    HapticFeedback.lightImpact();

    // Bullet trail
    _bulletTrails.add(WzBulletTrail(
      x1: _playerStrafe, y1: 1.0,
      x2: _crosshairPos.dx, y2: _crosshairPos.dy,
      life: 1.0, color: _currentWeapon.bulletColor,
    ));

    // Special weapon effects
    if (_currentWeapon.type == WzWeaponType.grenadeLauncher ||
        _currentWeapon.type == WzWeaponType.laserBeam ||
        _currentWeapon.type == WzWeaponType.plasmaCannon ||
        _currentWeapon.type == WzWeaponType.railgun) {
      _spawnExplosions(_crosshairPos.dx, _crosshairPos.dy, 15);
    }

    bool hitAny = false;
    double hitRadius = _currentWeapon.spreadRadius;
    // Shotgun hits multiple pellets
    int pellets = _currentWeapon.type == WzWeaponType.shotgun ? 6 : 1;

    for (int pellet = 0; pellet < pellets; pellet++) {
      double aimX = _crosshairPos.dx + (_rnd.nextDouble() - 0.5) * hitRadius * 2;
      double aimY = _crosshairPos.dy + (_rnd.nextDouble() - 0.5) * hitRadius * 2;

      for (int i = _enemies.length - 1; i >= 0; i--) {
        if (_enemies[i].isDying) continue;
        var e = _enemies[i];
        double vOff = _playerStrafe - 0.5;
        double sx = e.x - vOff * (1.0 - e.depth);
        double sy = 0.42 + e.depth * 0.42;
        double esz = hitRadius + e.depth * 0.10;
        double dx = sx - aimX, dy = sy - aimY;
        if (sqrt(dx * dx + dy * dy) < esz) {
          double dmg = _currentWeapon.damage;
          if (_currentWeapon.type == WzWeaponType.railgun) {
            // Railgun pierces all enemies
            e.hp -= dmg.toInt();
            _spawnParticles(sx, sy, e.type, 20);
            if (e.hp <= 0) _killEnemy(i);
            continue;
          }
          e.hp -= dmg.toInt();
          hitAny = true;
          _spawnParticles(sx, sy, e.type, 12);
          if (e.hp <= 0) _killEnemy(i);
          if (_currentWeapon.type != WzWeaponType.shotgun) break;
        }
      }
    }
    if (!hitAny && _currentWeapon.type != WzWeaponType.grenadeLauncher) {
      _comboKills = 0;
    }
    if (_currentWeapon.ammo == 0 && _currentWeapon.totalAmmo > 0) _reload();
    setState(() {});
  }

  void _killEnemy(int idx) {
    if (idx < 0 || idx >= _enemies.length) return;
    var e = _enemies[idx];
    e.isDying = true;
    e.dieTimer = 0.4;
    _comboKills++;
    _comboTimer = 3.0;
    int pts = (e.type == 0 ? 100 : e.type == 1 ? 300 : 500) * (1 + _comboKills ~/ 3);
    _score += pts;
    _kills++;
    _coins += e.type == 1 ? 30 : e.type == 2 ? 50 : 10;
    HapticFeedback.mediumImpact();
  }

  void _reload() {
    if (_currentWeapon.isReloading || _currentWeapon.ammo == _currentWeapon.clipSize) return;
    if (_currentWeapon.totalAmmo <= 0) return;
    _currentWeapon.isReloading = true;
    _currentWeapon.reloadProgress = 0;
    HapticFeedback.mediumImpact();
  }

  void _throwGrenade() {
    if (_grenades <= 0) return;
    _grenades--;
    HapticFeedback.heavyImpact();
    _spawnExplosions(_crosshairPos.dx, _crosshairPos.dy, 30);
    for (int i = _enemies.length - 1; i >= 0; i--) {
      var e = _enemies[i];
      double vOff = _playerStrafe - 0.5;
      double sx = e.x - vOff * (1.0 - e.depth);
      double sy = 0.42 + e.depth * 0.42;
      double dx = sx - _crosshairPos.dx, dy = sy - _crosshairPos.dy;
      if (sqrt(dx * dx + dy * dy) < 0.25) _killEnemy(i);
    }
    setState(() {});
  }

  void _spawnParticles(double x, double y, int enemyType, int count) {
    Color c = enemyType == 0 ? kNeonRed : enemyType == 1 ? kNeonOrange : kNeonPurple;
    for (int i = 0; i < count; i++) {
      double angle = _rnd.nextDouble() * 2 * pi;
      double spd = 0.2 + _rnd.nextDouble() * 0.5;
      _particles.add(WzParticle(
        x: x, y: y,
        vx: cos(angle) * spd,
        vy: sin(angle) * spd - 0.3,
        life: 0.3 + _rnd.nextDouble() * 0.5,
        color: c,
        size: 2 + _rnd.nextDouble() * 4,
      ));
    }
  }

  void _spawnExplosions(double x, double y, int count) {
    for (int i = 0; i < count; i++) {
      double angle = _rnd.nextDouble() * 2 * pi;
      double spd = 0.3 + _rnd.nextDouble() * 0.8;
      _particles.add(WzParticle(
        x: x, y: y,
        vx: cos(angle) * spd,
        vy: sin(angle) * spd - 0.5,
        life: 0.5 + _rnd.nextDouble() * 0.7,
        color: _rnd.nextBool() ? kNeonOrange : kNeonYellow,
        size: 4 + _rnd.nextDouble() * 8,
      ));
    }
  }

  void _switchWeapon(int idx) {
    if (idx >= 0 && idx < _weapons.length) {
      setState(() => _currentWeaponIdx = idx);
      HapticFeedback.selectionClick();
    }
  }

  @override
  void dispose() {
    _gameLoop.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: kDarkBg,
      body: Stack(children: [
        // GAME CANVAS
        if (_isPlaying || _isGameOver)
          Positioned.fill(child: CustomPaint(
            painter: WzPainter(
              enemies: List.from(_enemies),
              particles: List.from(_particles),
              bulletTrails: List.from(_bulletTrails),
              crosshair: _crosshairPos,
              strafe: _playerStrafe,
              damageFlash: _damageFlash,
              screenShake: _screenShake,
              currentWeapon: _currentWeapon,
            ),
          )),

        // HUD
        if (_isPlaying && !_isGameOver && !_showDialogue && !_showShop)
          _buildHUD(),

        // CONTROLS
        if (_isPlaying && !_isGameOver && !_showDialogue && !_showShop)
          _buildControls(),

        // DIALOGUE BOX
        if (_showDialogue && _currentDialogue != null)
          _buildDialogueBox(),

        // SHOP
        if (_showShop)
          _buildShop(),

        // START SCREEN
        if (!_isPlaying && !_isGameOver)
          _buildStartScreen(),

        // GAME OVER
        if (_isGameOver)
          _buildGameOverScreen(),

        // Between waves overlay
        if (_isBetweenWaves && !_showDialogue && !_showShop)
          Center(child: Text(
            'WAVE ${_wave + 1}\nINCOMING!',
            textAlign: TextAlign.center,
            style: TextStyle(
              color: kNeonRed,
              fontSize: 42,
              fontWeight: FontWeight.w900,
              letterSpacing: 4,
              shadows: [Shadow(color: kNeonRed, blurRadius: 20)],
            ),
          )),
      ]),
    );
  }

  Widget _buildHUD() {
    return Stack(children: [
      // Top left — wave, score, kills
      Positioned(top: 44, left: 16, child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        _hudText('WAVE $_wave', kNeonRed, 22),
        _hudText('SCORE: $_score', Colors.white, 18),
        _hudText('KILLS: $_kills', Colors.white70, 14),
        if (_comboKills >= 3)
          _hudText('COMBO x$_comboKills!', kNeonYellow, 16),
        if (_armor > 0)
          _hudText('ARMOR: ${_armor.toInt()}', Colors.lightBlue, 13),
      ])),

      // Health bar
      Positioned(top: 44, right: 16, child: Column(crossAxisAlignment: CrossAxisAlignment.end, children: [
        Row(children: [
          Icon(Icons.favorite, color: kNeonRed, size: 18),
          const SizedBox(width: 6),
          _buildBar(_health / _maxHealth, kNeonGreen, kNeonRed, 100, 10),
        ]),
        const SizedBox(height: 6),
        _hudText('GRENADES: $_grenades', kNeonOrange, 13),
        _hudText('COINS: $_coins', kNeonGold, 13),
        const SizedBox(height: 4),
        _hudText(_currentWeapon.name, _currentWeapon.bulletColor, 14),
        if (_currentWeapon.isReloading)
          Column(crossAxisAlignment: CrossAxisAlignment.end, children: [
            _hudText('RELOADING...', kNeonYellow, 12),
            _buildBar(_currentWeapon.reloadProgress, kNeonYellow, Colors.white12, 80, 5),
          ])
        else
          _hudText('${_currentWeapon.ammo}/${_currentWeapon.totalAmmo}',
            _currentWeapon.ammo < 5 ? kNeonRed : Colors.white, 13),
      ])),

      // Weapon selector (bottom center scrollable)
      Positioned(bottom: 210, left: 0, right: 0, child: SizedBox(
        height: 56,
        child: ListView.builder(
          scrollDirection: Axis.horizontal,
          padding: const EdgeInsets.symmetric(horizontal: 8),
          itemCount: _weapons.length,
          itemBuilder: (_, i) {
            bool selected = i == _currentWeaponIdx;
            var w = _weapons[i];
            return GestureDetector(
              onTap: () => _switchWeapon(i),
              child: AnimatedContainer(
                duration: const Duration(milliseconds: 150),
                margin: const EdgeInsets.symmetric(horizontal: 4),
                padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
                decoration: BoxDecoration(
                  color: selected ? w.bulletColor.withValues(alpha: 0.25) : Colors.black45,
                  borderRadius: BorderRadius.circular(10),
                  border: Border.all(color: selected ? w.bulletColor : Colors.white12, width: selected ? 2 : 1),
                  boxShadow: selected ? [BoxShadow(color: w.bulletColor, blurRadius: 10)] : [],
                ),
                child: Column(mainAxisSize: MainAxisSize.min, children: [
                  Text(w.name.split(' ').first, style: TextStyle(
                    color: selected ? w.bulletColor : Colors.white54,
                    fontSize: 9, fontWeight: FontWeight.bold,
                  )),
                  Text('${w.ammo}', style: TextStyle(
                    color: selected ? Colors.white : Colors.white38,
                    fontSize: 12, fontWeight: FontWeight.w900,
                  )),
                ]),
              ),
            );
          },
        ),
      )),
    ]);
  }

  Widget _buildControls() {
    return Positioned(bottom: 16, left: 16, right: 16, child: SizedBox(
      height: 190,
      child: Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [
        // LEFT JOYSTICK — move/strafe
        VirtualJoystick(
          size: 120,
          baseColor: Colors.white12,
          knobColor: kNeonGreen,
          onDirectionChanged: (dir) {
            double spd = _perkSpeedBoost ? _moveSpeed * 1.5 : _moveSpeed;
            _playerStrafe = (_playerStrafe + dir.dx * spd).clamp(0.0, 1.0);
          },
        ),

        // ACTION BUTTONS
        Row(children: [
          Column(mainAxisAlignment: MainAxisAlignment.center, children: [
            ActionButton(icon: Icons.refresh_rounded, color: kNeonYellow,
              label: 'RELOAD', onPressed: _reload, size: 52),
            const SizedBox(height: 8),
            ActionButton(icon: Icons.local_fire_department, color: kNeonOrange,
              label: 'NADE', onPressed: _throwGrenade, size: 52),
          ]),
          const SizedBox(width: 12),

          // RIGHT JOYSTICK — aim
          VirtualJoystick(
            size: 120,
            baseColor: Colors.white12,
            knobColor: kNeonRed,
            onDirectionChanged: (dir) {
              _crosshairPos = Offset(
                (_crosshairPos.dx + dir.dx * 0.022).clamp(0.05, 0.95),
                (_crosshairPos.dy + dir.dy * 0.022).clamp(0.15, 0.75),
              );
            },
          ),
          const SizedBox(width: 12),

          // FIRE BUTTON
          ActionButton(
            icon: Icons.gps_fixed,
            color: kNeonRed,
            label: 'FIRE',
            onPressStart: () { _isFiring = true; _fire(); },
            onPressEnd: () => _isFiring = false,
            onPressed: _fire,
            size: 80,
          ),
        ]),
      ]),
    ));
  }

  Widget _buildDialogueBox() {
    final d = _currentDialogue!;
    return Positioned(bottom: 0, left: 0, right: 0, child: Container(
      margin: const EdgeInsets.all(12),
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: Colors.black87,
        border: Border.all(color: d.speakerColor, width: 2),
        borderRadius: BorderRadius.circular(16),
        boxShadow: [BoxShadow(color: d.speakerColor.withValues(alpha: 0.4), blurRadius: 20)],
      ),
      child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          CircleAvatar(backgroundColor: d.speakerColor, radius: 16,
            child: Text(d.speaker[0], style: const TextStyle(color: Colors.black, fontWeight: FontWeight.bold))),
          const SizedBox(width: 10),
          Text(d.speaker, style: TextStyle(color: d.speakerColor, fontWeight: FontWeight.w900, fontSize: 14, letterSpacing: 2)),
        ]),
        const SizedBox(height: 10),
        Text(d.message, style: const TextStyle(color: Colors.white, fontSize: 14, height: 1.5)),
        const SizedBox(height: 12),
        if (d.choices != null)
          Wrap(spacing: 8, children: d.choices!.asMap().entries.map((e) =>
            ElevatedButton(
              style: ElevatedButton.styleFrom(backgroundColor: d.speakerColor.withValues(alpha: 0.3),
                side: BorderSide(color: d.speakerColor)),
              onPressed: () => _advanceDialogue(e.key),
              child: Text(e.value, style: const TextStyle(color: Colors.white, fontSize: 12)),
            )
          ).toList())
        else
          Align(alignment: Alignment.centerRight,
            child: TextButton(onPressed: () => _advanceDialogue(-1),
              child: Text('CONTINUE ▶', style: TextStyle(color: d.speakerColor, letterSpacing: 2)))),
      ]),
    ));
  }

  Widget _buildShop() {
    return Container(
      color: Colors.black87,
      child: SafeArea(child: SingleChildScrollView(
        padding: const EdgeInsets.all(16),
        child: Column(children: [
          Text(' ARMORY — WAVE ${_wave + 1} PREP', style: TextStyle(
            color: kNeonGold, fontSize: 22, fontWeight: FontWeight.w900, letterSpacing: 3,
            shadows: [Shadow(color: kNeonGold, blurRadius: 15)],
          )),
          Text(' COINS: $_coins', style: const TextStyle(color: Colors.white, fontSize: 16)),
          const SizedBox(height: 16),
          const Text('PERKS', style: TextStyle(color: Colors.white70, fontSize: 14, letterSpacing: 2)),
          const SizedBox(height: 8),
          _shopPerk(' DOUBLE TAP', 'Fire 40% faster', _perkDoubleTapCost, _perkDoubleTap, () {
            if (_coins >= _perkDoubleTapCost && !_perkDoubleTap) {
              setState(() { _coins -= _perkDoubleTapCost; _perkDoubleTap = true; });
            }
          }),
          _shopPerk(' SPEED BOOST', 'Move 50% faster', _perkSpeedBoostCost, _perkSpeedBoost, () {
            if (_coins >= _perkSpeedBoostCost && !_perkSpeedBoost) {
              setState(() { _coins -= _perkSpeedBoostCost; _perkSpeedBoost = true; });
            }
          }),
          _shopPerk(' ARMOR PLATING', 'Reduce damage 30%', _perkArmorPlatingCost, _perkArmorPlating, () {
            if (_coins >= _perkArmorPlatingCost && !_perkArmorPlating) {
              setState(() { _coins -= _perkArmorPlatingCost; _perkArmorPlating = true; });
            }
          }),
          const SizedBox(height: 16),
          const Text('WEAPON REFILL', style: TextStyle(color: Colors.white70, fontSize: 14, letterSpacing: 2)),
          const SizedBox(height: 8),
          ...List.generate(_weapons.length, (i) {
            var w = _weapons[i];
            int cost = _weaponUpgradeCost;
            return _shopWeapon(w.name, w.bulletColor, cost, w.ammo < w.clipSize, () {
              if (_coins >= cost) {
                setState(() {
                  _coins -= cost;
                  w.totalAmmo = w.maxAmmo;
                  w.ammo = w.clipSize;
                });
              }
            });
          }),
          const SizedBox(height: 24),
          ElevatedButton.icon(
            style: ElevatedButton.styleFrom(backgroundColor: kNeonGreen,
              padding: const EdgeInsets.symmetric(horizontal: 32, vertical: 14)),
            icon: const Icon(Icons.play_arrow_rounded, color: Colors.black),
            label: const Text('NEXT WAVE', style: TextStyle(color: Colors.black, fontWeight: FontWeight.w900, fontSize: 16)),
            onPressed: () {
              setState(() {
                _showShop = false;
                _wave++;
                _enemiesToSpawn = 5 + _wave * 3;
                _spawnTimer = 0;
                if (_wave <= _waveDialogues.length) _startDialogue(_waveDialogues[_wave - 1]);
              });
            },
          ),
        ]),
      )),
    );
  }

