    return Container(
      margin: const EdgeInsets.only(bottom: 8),
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: owned ? Colors.green.withValues(alpha: 0.15) : Colors.white.withValues(alpha: 0.05),
        borderRadius: BorderRadius.circular(10),
        border: Border.all(color: owned ? kNeonGreen : Colors.white24),
      ),
      child: Row(children: [
        Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Text(name, style: const TextStyle(color: Colors.white, fontWeight: FontWeight.bold)),
          Text(desc, style: const TextStyle(color: Colors.white54, fontSize: 12)),
        ])),
        owned
            ? const Text('OWNED ', style: TextStyle(color: kNeonGreen, fontWeight: FontWeight.bold))
            : ElevatedButton(
                style: ElevatedButton.styleFrom(
                  backgroundColor: _coins >= cost ? kNeonGold.withValues(alpha: 0.3) : Colors.white10,
                  side: BorderSide(color: _coins >= cost ? kNeonGold : Colors.white12),
                ),
                onPressed: onBuy,
                child: Text('$cost ', style: const TextStyle(color: Colors.white, fontSize: 12)),
              ),
      ]),
    );
  }

  Widget _shopWeapon(String name, Color color, int cost, bool needsRefill, VoidCallback onBuy) {
    return Container(
      margin: const EdgeInsets.only(bottom: 6),
      padding: const EdgeInsets.all(10),
      decoration: BoxDecoration(
        color: Colors.white.withValues(alpha: 0.04),
        borderRadius: BorderRadius.circular(8),
        border: Border.all(color: Colors.white12),
      ),
      child: Row(children: [
        Container(width: 12, height: 12, decoration: BoxDecoration(color: color, shape: BoxShape.circle,
          boxShadow: [BoxShadow(color: color, blurRadius: 8)])),
        const SizedBox(width: 8),
        Expanded(child: Text(name, style: const TextStyle(color: Colors.white70, fontSize: 12))),
        if (needsRefill)
          ElevatedButton(
            style: ElevatedButton.styleFrom(
              backgroundColor: _coins >= cost ? color.withValues(alpha: 0.3) : Colors.white10,
              side: BorderSide(color: _coins >= cost ? color : Colors.white12),
              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
            ),
            onPressed: onBuy,
            child: Text('REFILL $cost COINS', style: const TextStyle(color: Colors.white, fontSize: 11)),
          )
        else
          Text('FULL', style: TextStyle(color: kNeonGreen, fontSize: 12, fontWeight: FontWeight.bold)),
      ]),
    );
  }

  Widget _buildStartScreen() {
    return Center(child: Container(
      margin: const EdgeInsets.all(24),
      padding: const EdgeInsets.all(28),
      decoration: BoxDecoration(
        color: Colors.black87,
        border: Border.all(color: kNeonRed, width: 2),
        borderRadius: BorderRadius.circular(24),
        boxShadow: [BoxShadow(color: kNeonRed.withValues(alpha: 0.4), blurRadius: 40, spreadRadius: 5)],
      ),
      child: Column(mainAxisSize: MainAxisSize.min, children: [
        Text('WARZONE BLITZ', style: TextStyle(
          color: kNeonRed, fontSize: 32, fontWeight: FontWeight.w900, letterSpacing: 4,
          shadows: [Shadow(color: kNeonRed, blurRadius: 20)],
        )),
        const SizedBox(height: 8),
        Text('OPERATION NEON STORM', style: TextStyle(color: kNeonOrange, fontSize: 14, letterSpacing: 3)),
        const SizedBox(height: 4),
        const Text('Commander Striker Vance vs The Cyber-Grip Faction',
          style: TextStyle(color: Colors.white60, fontSize: 12), textAlign: TextAlign.center),
        const SizedBox(height: 20),
        Text('HIGH SCORE: $_highScore', style: TextStyle(color: kNeonGold, fontSize: 16, fontWeight: FontWeight.bold)),
        const SizedBox(height: 24),
        const Text('SELECT DIFFICULTY', style: TextStyle(color: Colors.white54, fontSize: 13, letterSpacing: 3)),
        const SizedBox(height: 12),
        Row(mainAxisSize: MainAxisSize.min, children: [
          _diffBtn('EASY', Colors.green, () => _startGame('Easy')),
          const SizedBox(width: 10),
          _diffBtn('MEDIUM', kNeonOrange, () => _startGame('Medium')),
          const SizedBox(width: 10),
          _diffBtn('HARD', kNeonRed, () => _startGame('Hard')),
        ]),
        const SizedBox(height: 20),
        const OnlinePlayersPanel(gameName: 'Warzone Blitz'),
        const SizedBox(height: 12),
        TextButton(
          onPressed: () => Navigator.pop(context),
          child: const Text('◀ BACK', style: TextStyle(color: Colors.white38)),
        ),
      ]),
    ));
  }

  Widget _buildGameOverScreen() {
    bool newRecord = _score > _highScore && _score > 0;
    return Center(child: Container(
      margin: const EdgeInsets.all(24),
      padding: const EdgeInsets.all(28),
      decoration: BoxDecoration(
        color: Colors.black87,
        border: Border.all(color: kNeonRed, width: 2),
        borderRadius: BorderRadius.circular(24),
        boxShadow: [BoxShadow(color: kNeonRed.withValues(alpha: 0.5), blurRadius: 40)],
      ),
      child: Column(mainAxisSize: MainAxisSize.min, children: [
        const Text('MISSION FAILED', style: TextStyle(color: kNeonRed, fontSize: 36, fontWeight: FontWeight.w900, letterSpacing: 4)),
        const SizedBox(height: 16),
        Text('SCORE: $_score', style: const TextStyle(color: Colors.white, fontSize: 24, fontWeight: FontWeight.bold)),
        Text('WAVE REACHED: $_wave', style: const TextStyle(color: Colors.white70, fontSize: 16)),
        Text('KILLS: $_kills', style: const TextStyle(color: Colors.white70, fontSize: 14)),
        if (newRecord) ...[
          const SizedBox(height: 8),
          Text(' NEW HIGH SCORE!', style: TextStyle(color: kNeonGold, fontSize: 18,
            fontWeight: FontWeight.w900, shadows: [Shadow(color: kNeonGold, blurRadius: 15)])),
        ],
        const SizedBox(height: 24),
        Row(mainAxisSize: MainAxisSize.min, children: [
          ElevatedButton.icon(
            style: ElevatedButton.styleFrom(backgroundColor: kNeonRed, padding: const EdgeInsets.all(14)),
            icon: const Icon(Icons.replay, color: Colors.white),
            label: const Text('RETRY', style: TextStyle(color: Colors.white, fontWeight: FontWeight.bold)),
            onPressed: () => _startGame(_difficulty),
          ),
          const SizedBox(width: 12),
          OutlinedButton(
            style: OutlinedButton.styleFrom(side: const BorderSide(color: Colors.white30)),
            onPressed: () { setState(() { _isGameOver = false; _isPlaying = false; }); },
            child: const Text('MENU', style: TextStyle(color: Colors.white54)),
          ),
        ]),
      ]),
    ));
  }

  Widget _diffBtn(String label, Color color, VoidCallback onTap) {
    return ElevatedButton(
      style: ElevatedButton.styleFrom(
        backgroundColor: color.withValues(alpha: 0.2),
        side: BorderSide(color: color),
        padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 10),
      ),
      onPressed: onTap,
      child: Text(label, style: TextStyle(color: color, fontWeight: FontWeight.bold)),
    );
  }

  Widget _hudText(String t, Color c, double size) => Text(t, style: TextStyle(
    color: c, fontSize: size, fontWeight: FontWeight.bold,
    shadows: [Shadow(color: c, blurRadius: 6)],
  ));

  Widget _buildBar(double frac, Color fg, Color bg, double w, double h) => Container(
    width: w, height: h, decoration: BoxDecoration(color: bg, borderRadius: BorderRadius.circular(h)),
    child: FractionallySizedBox(
      widthFactor: frac.clamp(0.0, 1.0),
      alignment: Alignment.centerLeft,
      child: Container(decoration: BoxDecoration(
        color: fg,
        borderRadius: BorderRadius.circular(h),
        boxShadow: [BoxShadow(color: fg, blurRadius: 4)],
      )),
    ),
  );
}

// ============================================================
// WARZONE BLITZ PAINTER
// ============================================================
class WzPainter extends CustomPainter {
  final List<WzEnemy> enemies;
  final List<WzParticle> particles;
  final List<WzBulletTrail> bulletTrails;
  final Offset crosshair;
  final double strafe, damageFlash, screenShake;
  final WzWeapon currentWeapon;

  WzPainter({
    required this.enemies, required this.particles, required this.bulletTrails,
    required this.crosshair, required this.strafe, required this.damageFlash,
    required this.screenShake, required this.currentWeapon,
  });

  @override
  void paint(Canvas canvas, Size size) {
    // Screen shake
    if (screenShake > 0) {
      canvas.save();
      canvas.translate((Random().nextDouble() - 0.5) * screenShake * 12,
          (Random().nextDouble() - 0.5) * screenShake * 8);
    }

    // Background
    canvas.drawRect(Rect.fromLTWH(0, 0, size.width, size.height),
        Paint()..color = const Color(0xFF020510));

    // Sky gradient
    final skyPaint = Paint()..shader = LinearGradient(
      begin: Alignment.topCenter, end: Alignment.bottomCenter,
      colors: [const Color(0xFF080820), const Color(0xFF101030)],
    ).createShader(Rect.fromLTWH(0, 0, size.width, size.height * 0.5));
    canvas.drawRect(Rect.fromLTWH(0, 0, size.width, size.height * 0.5), skyPaint);

    // Stars
    final starPaint = Paint()..color = Colors.white30..strokeWidth = 1;
    final rnd = Random(42);
    for (int i = 0; i < 60; i++) {
      canvas.drawCircle(
        Offset(rnd.nextDouble() * size.width, rnd.nextDouble() * size.height * 0.4),
        0.8 + rnd.nextDouble() * 1.2, starPaint,
      );
    }

    final double horizonY = size.height * 0.42;
    final double viewOffsetX = (strafe - 0.5) * size.width * 0.8;
    final Offset vp = Offset(size.width / 2 - viewOffsetX, horizonY);

    // Ground
    final groundPaint = Paint()..color = const Color(0xFF0A1808);
    canvas.drawRect(Rect.fromLTRB(0, horizonY, size.width, size.height), groundPaint);

    // Perspective grid
    final gridPaint = Paint()..color = kNeonGreen.withValues(alpha: 0.25)..strokeWidth = 1.0;
    for (int i = -8; i <= 8; i++) {
      double sx = size.width / 2 + i * size.width / 5 - viewOffsetX * 2.5;
      canvas.drawLine(Offset(sx, size.height), vp, gridPaint);
    }
    for (int i = 1; i <= 14; i++) {
      double t = i / 14.0;
      double y = horizonY + pow(t, 1.8) * (size.height - horizonY);
      canvas.drawLine(Offset(0, y), Offset(size.width, y),
          Paint()..color = kNeonGreen.withValues(alpha: 0.12 + t * 0.08)..strokeWidth = 0.5 + t);
    }

    // Bunkers in distance
    _drawBunkers(canvas, size, horizonY, viewOffsetX);

    // Bullet trails
    for (var t in bulletTrails) {
      final p = Paint()..color = t.color.withValues(alpha: t.life)
        ..strokeWidth = 1.5 + t.life * 2..strokeCap = StrokeCap.round;
      canvas.drawLine(
        Offset(t.x1 * size.width, size.height),
        Offset(t.x2 * size.width, t.y2 * size.height), p,
      );
    }

    // Enemies
    final sorted = List<WzEnemy>.from(enemies)..sort((a, b) => a.depth.compareTo(b.depth));
    for (var e in sorted) {
      double vOff = strafe - 0.5;
      double sx = (e.x - vOff * (1.0 - e.depth)) * size.width;
      double sy = horizonY + e.depth * (size.height - horizonY);
      double radius = 12 + e.depth * 55;
      double alpha = e.isDying ? e.dieTimer * 2.5 : 1.0;
      alpha = alpha.clamp(0.0, 1.0);

      Color c = e.type == 0 ? kNeonRed : e.type == 1 ? kNeonOrange : kNeonPurple;
      Paint glow = Paint()..color = c.withValues(alpha: alpha * 0.4)
        ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 14);
      Paint fill = Paint()..color = c.withValues(alpha: alpha * 0.8);

      if (e.type == 1) {
        // Tank — rectangle body + turret
        Rect body = Rect.fromCenter(center: Offset(sx, sy - radius * 0.5), width: radius * 2.2, height: radius * 1.2);
        canvas.drawRect(body, glow);
        canvas.drawRRect(RRect.fromRectAndRadius(body, const Radius.circular(4)), fill);
        canvas.drawLine(Offset(sx, sy - radius * 0.5), Offset(sx, sy - radius * 1.5),
            Paint()..color = c..strokeWidth = 4..strokeCap = StrokeCap.round);
      } else if (e.type == 2) {
        // Sniper — tall narrow figure
        canvas.drawOval(Rect.fromCenter(center: Offset(sx, sy - radius), width: radius * 0.6, height: radius * 2.2), glow);
        canvas.drawOval(Rect.fromCenter(center: Offset(sx, sy - radius), width: radius * 0.5, height: radius * 2.0), fill);
        // Sniper scope glint
        canvas.drawCircle(Offset(sx + radius * 0.3, sy - radius * 1.5), 4,
            Paint()..color = Colors.white..maskFilter = const MaskFilter.blur(BlurStyle.normal, 3));
      } else {
        // Soldier — humanoid
        canvas.drawCircle(Offset(sx, sy - radius * 1.2), radius * 0.45, glow);
        canvas.drawCircle(Offset(sx, sy - radius * 1.2), radius * 0.4, fill); // head
        canvas.drawRect(Rect.fromCenter(center: Offset(sx, sy - radius * 0.55), width: radius * 0.8, height: radius * 0.9), fill); // body
      }

      // HP bar above enemy
      if (!e.isDying && e.maxHp > 1) {
        double bw = radius * 2;
        Rect bar = Rect.fromLTWH(sx - bw / 2, sy - radius * 1.9 - 8, bw, 5);
        canvas.drawRect(bar, Paint()..color = Colors.black45);
        canvas.drawRect(Rect.fromLTWH(bar.left, bar.top, bw * e.hp / e.maxHp, 5),
            Paint()..color = kNeonGreen);
      }
    }

    // Particles
    for (var p in particles) {
      double a = (p.life / p.maxLife).clamp(0.0, 1.0);
      canvas.drawCircle(
        Offset(p.x * size.width, p.y * size.height),
        p.size * a,
        Paint()..color = p.color.withValues(alpha: a)
          ..maskFilter = MaskFilter.blur(BlurStyle.normal, p.size * 0.5),
      );
    }

    // Crosshair
    _drawCrosshair(canvas, size, currentWeapon);

    // Damage vignette flash
    if (damageFlash > 0) {
      canvas.drawRect(
        Rect.fromLTWH(0, 0, size.width, size.height),
        Paint()..color = Colors.red.withValues(alpha: damageFlash * 0.45),
      );
      // Draw red border
      canvas.drawRect(
        Rect.fromLTWH(0, 0, size.width, size.height),
        Paint()..color = Colors.red.withValues(alpha: damageFlash * 0.7)
          ..style = PaintingStyle.stroke..strokeWidth = 20,
      );
    }

    if (screenShake > 0) canvas.restore();
  }

  void _drawBunkers(Canvas canvas, Size size, double horizonY, double viewOffsetX) {
    final bunkerPaint = Paint()..color = const Color(0xFF1A2010);
    List<double> bunkerXs = [0.1, 0.35, 0.65, 0.88];
    for (double bx in bunkerXs) {
      double sx = (bx - (strafe - 0.5) * 0.6) * size.width;
      double bw = 60 + (bx * 20);
      double bh = 35 + (bx * 15);
      canvas.drawRect(Rect.fromLTWH(sx - bw / 2, horizonY - bh, bw, bh), bunkerPaint);
      // Window slots
      for (int j = 0; j < 3; j++) {
        canvas.drawRect(
          Rect.fromLTWH(sx - bw / 2 + 8 + j * (bw - 16) / 3, horizonY - bh + 8, 8, 14),
          Paint()..color = kNeonGreen.withValues(alpha: 0.3),
        );
      }
    }
  }

  void _drawCrosshair(Canvas canvas, Size size, WzWeapon weapon) {
    Offset center = Offset(crosshair.dx * size.width, crosshair.dy * size.height);
    Color chColor = weapon.bulletColor;
    Paint chp = Paint()..color = chColor..strokeWidth = 1.5..style = PaintingStyle.stroke;
    Paint dot = Paint()..color = Colors.white..style = PaintingStyle.fill;

    switch (weapon.type) {
      case WzWeaponType.sniperRifle:
        canvas.drawCircle(center, 35, chp..strokeWidth = 1.0);
        canvas.drawCircle(center, 5, chp..strokeWidth = 1.0);
        canvas.drawLine(center - const Offset(50, 0), center + const Offset(50, 0), chp);
        canvas.drawLine(center - const Offset(0, 50), center + const Offset(0, 50), chp);
        break;
      case WzWeaponType.shotgun:
        canvas.drawCircle(center, 20, chp..strokeWidth = 1.5);
        for (int i = 0; i < 6; i++) {
          double angle = i * pi / 3;
          canvas.drawLine(center + Offset(cos(angle) * 22, sin(angle) * 22),
              center + Offset(cos(angle) * 30, sin(angle) * 30), chp);
        }
        break;
      case WzWeaponType.laserBeam:
        canvas.drawRect(Rect.fromCenter(center: center, width: 20, height: 2), chp..style = PaintingStyle.fill);
        canvas.drawRect(Rect.fromCenter(center: center, width: 2, height: 20), chp..style = PaintingStyle.fill);
        canvas.drawCircle(center, 2, dot..color = chColor);
        break;
      case WzWeaponType.railgun:
        canvas.drawCircle(center, 8, chp..strokeWidth = 3.0);
        for (int i = 0; i < 4; i++) {
          double a = i * pi / 2 + pi / 4;
          canvas.drawLine(center + Offset(cos(a) * 10, sin(a) * 10),
              center + Offset(cos(a) * 40, sin(a) * 40), chp..strokeWidth = 1.5);
        }
        break;
      default:
        canvas.drawCircle(center, 16, chp..strokeWidth = 1.5);
        canvas.drawLine(center - const Offset(24, 0), center - const Offset(8, 0), chp);
        canvas.drawLine(center + const Offset(8, 0), center + const Offset(24, 0), chp);
        canvas.drawLine(center - const Offset(0, 24), center - const Offset(0, 8), chp);
        canvas.drawLine(center + const Offset(0, 8), center + const Offset(0, 24), chp);
        canvas.drawCircle(center, 2, dot);
    }
  }

  @override
  bool shouldRepaint(covariant CustomPainter old) => true;
}

// ============================================================
// DATA MODELS — CYBER HUNT
// ============================================================
enum ChDroneType { scout, hunter, boss }

class ChDrone {
  double x, y, depth, speed;
  ChDroneType type;
  int hp, maxHp;
  double strafeAngle = 0;
  bool isDying = false;
  double dieTimer = 0;
  ChDrone({required this.x, required this.y, required this.depth, required this.type,
    required this.hp, required this.speed}) : maxHp = hp;
}

class ChParticle {
  double x, y, vx, vy, life, maxLife, size;
  Color color;
  ChParticle({required this.x, required this.y, required this.vx, required this.vy,
    required this.life, required this.color, this.size = 3}) : maxLife = life;
}

class ChHackSequence {
  final List<Color> sequence;
  final List<Color> playerInput;
  final String reward;
  ChHackSequence({required this.sequence, required this.reward}) : playerInput = [];
}

// ============================================================
// CYBER HUNT GAME
// ============================================================
class CyberHuntGame extends StatefulWidget {
  const CyberHuntGame({Key? key}) : super(key: key);
  @override
  State<CyberHuntGame> createState() => _CyberHuntGameState();
}

class _CyberHuntGameState extends State<CyberHuntGame> with TickerProviderStateMixin {
  late AnimationController _gameLoop;

  bool _isPlaying = false;
  bool _isGameOver = false;
  bool _showHack = false;
  bool _bossPhase = false;
  String _bossDialogue = '';
  String _hackRewardMsg = '';
  double _hackRewardTimer = 0;

  double _health = 100;
  int _score = 0;
  int _highScore = 0;
  int _wave = 1;
  int _combo = 1;
  int _ammo = 25, _totalAmmo = 200;
  bool _isReloading = false;
  double _reloadProgress = 0;
  bool _hasShield = false;
  bool _isZoomed = false;
  double _shieldPulse = 0;

  // Boss
  double _bossHp = 0, _bossMaxHp = 0;
  int _bossPhaseIdx = 0;
  double _bossPhaseTimer = 0;

  // Movement
  Offset _crosshairPos = const Offset(0.5, 0.45);
  double _playerStrafe = 0.5;

  // Entities
  final List<ChDrone> _drones = [];
  final List<ChParticle> _particles = [];

  final Random _rnd = Random();
  double _spawnTimer = 0;
  int _dronesToSpawn = 5;

  double _damageFlash = 0;
  bool _isFiring = false;

  // Hacking mini-game
  ChHackSequence? _currentHack;
  final List<Color> _hackColors = [kNeonCyan, kNeonMagenta, kNeonGreen, kNeonOrange];

  // Boss dialogues
  final List<String> _bossDialogues = [
    'AEGIS-GUARDIAN: "Intruder detected. Initiating SHIELD OVERDRIVE protocol!"',
    'AEGIS-GUARDIAN: "Shields failing. Switching to LASER RAIN sequence!"',
    'AEGIS-GUARDIAN: "ERROR: CRITICAL FAILURE. INITIATING DRONE SWARM SUMMON!"',
    'AEGIS-GUARDIAN: "SYSTEM COLLAPSE IMMINENT... Zero, you will be deleted—"',
  ];

  @override
  void initState() {
    super.initState();
    _loadHighScore();
    _gameLoop = AnimationController(vsync: this, duration: const Duration(seconds: 1))..repeat();
    _gameLoop.addListener(_update);
  }

  Future<void> _loadHighScore() async {
    final prefs = await SharedPreferences.getInstance();
    setState(() => _highScore = prefs.getInt('hi_score_cyber_hunt') ?? 0);
  }

  Future<void> _saveHighScore() async {
    if (_score > _highScore) {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setInt('hi_score_cyber_hunt', _score);
      _highScore = _score;
    }
  }

  void _startGame() {
    setState(() {
      _isPlaying = true; _isGameOver = false; _showHack = false;
      _health = 100; _score = 0; _wave = 1; _combo = 1;
      _ammo = 25; _totalAmmo = 200; _isReloading = false;
      _hasShield = false; _isZoomed = false;
      _crosshairPos = const Offset(0.5, 0.45);
      _playerStrafe = 0.5;
      _drones.clear(); _particles.clear();
      _dronesToSpawn = 5; _spawnTimer = 0;
      _bossPhase = false; _bossHp = 0; _bossPhaseIdx = 0;
      _damageFlash = 0;
    });
    HapticFeedback.mediumImpact();
  }

  void _update() {
    if (!_isPlaying || _isGameOver || _showHack) return;
    const double dt = 1 / 60;

    if (_damageFlash > 0) _damageFlash -= dt * 3;
    if (_hackRewardTimer > 0) _hackRewardTimer -= dt;
    if (_shieldPulse > 0) _shieldPulse -= dt * 2;

    // Boss phase timer
    if (_bossPhase && _bossPhaseTimer > 0) {
      _bossPhaseTimer -= dt;
      if (_bossPhaseTimer <= 0) _nextBossPhase();
    }

    // Auto-fire
    if (_isFiring && !_isReloading && _ammo > 0) _fire();

    // Reload
    if (_isReloading) {
      _reloadProgress += dt / 1.5;
      if (_reloadProgress >= 1.0) {
        int need = 25 - _ammo;
        int from = _totalAmmo >= need ? need : _totalAmmo;
        _ammo += from; _totalAmmo -= from;
        _isReloading = false; _reloadProgress = 0;
      }
    }

    // Spawn
    if (_dronesToSpawn > 0 && _drones.where((d) => !d.isDying).length < 6 + _wave) {
      _spawnTimer += dt;
      if (_spawnTimer > (2.0 - _wave * 0.08).clamp(0.4, 2.0)) {
        _spawnDrone(); _spawnTimer = 0; _dronesToSpawn--;
      }
    }

    // Wave complete
    if (_dronesToSpawn == 0 && _drones.where((d) => !d.isDying).isEmpty) {
      _wave++;
      _dronesToSpawn = 5 + _wave * 2;
      _ammo = 25; _totalAmmo = (_totalAmmo + 50).clamp(0, 300);
      if (_rnd.nextBool()) _hasShield = true;
      _shieldPulse = 1.0;
      // Every 5th wave — BOSS
      if (_wave % 5 == 0) _spawnBoss();
    }

    // Update drones
    double t = DateTime.now().millisecondsSinceEpoch / 1000.0;
    for (int i = _drones.length - 1; i >= 0; i--) {
      var d = _drones[i];
      if (d.isDying) { d.dieTimer -= dt; if (d.dieTimer <= 0) _drones.removeAt(i); continue; }
      d.depth += d.speed * dt;
      d.x += sin(t * 1.5 + d.strafeAngle) * dt * 0.15;
      d.x = d.x.clamp(0.05, 0.95);
      if (d.depth >= 1.0) {
        _drones.removeAt(i);
        _takeDamage(d.type == ChDroneType.boss ? 50 : 20);
        _combo = 1;
      }
    }

    // Particles
    for (int i = _particles.length - 1; i >= 0; i--) {
      var p = _particles[i];
      p.life -= dt; p.x += p.vx * dt; p.y += p.vy * dt;
      if (p.life <= 0) _particles.removeAt(i);
    }

    setState(() {});
  }

  void _spawnDrone() {
    ChDroneType type = ChDroneType.scout;
    if (_wave > 2 && _rnd.nextDouble() > 0.55) type = ChDroneType.hunter;
    _drones.add(ChDrone(
      x: _rnd.nextDouble() * 0.75 + 0.12,
      y: _rnd.nextDouble() * 0.35 + 0.1,
      depth: 0.0,
      type: type,
      hp: type == ChDroneType.scout ? 1 : 3,
      speed: type == ChDroneType.scout ? 0.22 : 0.14,
    )..strafeAngle = _rnd.nextDouble() * pi * 2);
  }

  void _spawnBoss() {
    _bossPhase = true;
    _bossHp = 200 + _wave * 20;
    _bossMaxHp = _bossHp;
    _bossPhaseIdx = 0;
    _bossPhaseTimer = 12.0;
    _bossDialogue = _bossDialogues[0];
    _drones.add(ChDrone(
      x: 0.5, y: 0.15, depth: 0.1,
      type: ChDroneType.boss, hp: _bossHp.toInt(), speed: 0.04,
    ));
    HapticFeedback.heavyImpact();
  }

  void _nextBossPhase() {
    _bossPhaseIdx++;
    _bossPhaseTimer = 10.0;
    if (_bossPhaseIdx < _bossDialogues.length) {
      _bossDialogue = _bossDialogues[_bossPhaseIdx];
    }
    // Phase effects
    switch (_bossPhaseIdx) {
      case 1: // Laser Rain
        for (int i = 0; i < 6; i++) _spawnDrone();
        break;
      case 2: // Swarm Summon
        for (int i = 0; i < 10; i++) _spawnDrone();
        break;
      case 3:
        _bossPhase = false;
        break;
    }
  }

  void _takeDamage(double amt) {
    if (_hasShield) { _hasShield = false; HapticFeedback.lightImpact(); return; }
    _health -= amt;
    _damageFlash = 1.0;
    HapticFeedback.heavyImpact();
    if (_health <= 0) { _health = 0; _isGameOver = true; _isPlaying = false; _saveHighScore(); }
    setState(() {});
  }

  void _fire() {
    if (_isReloading || _ammo <= 0) { if (_ammo <= 0 && !_isReloading) { _isReloading = true; _reloadProgress = 0; } return; }
    _ammo--;
    HapticFeedback.lightImpact();
    bool hit = false;
    for (int i = _drones.length - 1; i >= 0; i--) {
      if (_drones[i].isDying) continue;
      var d = _drones[i];
      double vOff = _playerStrafe - 0.5;
      double sx = d.x - vOff * (1.0 - d.depth);
      double sy = d.y + d.depth * 0.2;
      if (_isZoomed) { sx = (sx - 0.5) * 0.5 + 0.5; sy = (sy - 0.45) * 0.5 + 0.45; }
      double hitR = 0.06 + d.depth * 0.08;
      double dx = sx - _crosshairPos.dx, dy = sy - _crosshairPos.dy;
      if (sqrt(dx * dx + dy * dy) < hitR) {
        d.hp--;
        hit = true;
        Color c = d.type == ChDroneType.scout ? kNeonCyan : d.type == ChDroneType.hunter ? kNeonMagenta : kNeonGold;
        for (int p = 0; p < 14; p++) {
          double ang = _rnd.nextDouble() * 2 * pi;
          double spd = 0.2 + _rnd.nextDouble() * 0.5;
          _particles.add(ChParticle(x: sx, y: sy, vx: cos(ang) * spd, vy: sin(ang) * spd,
              life: 0.4 + _rnd.nextDouble() * 0.4, color: c, size: 3 + _rnd.nextDouble() * 4));
        }
        if (d.hp <= 0) {
          d.isDying = true; d.dieTimer = 0.5;
          int pts = (d.type == ChDroneType.scout ? 150 : d.type == ChDroneType.hunter ? 350 : 1500) * _combo;
          if (_isZoomed) pts = (pts * 2.0).toInt();
          _score += pts;
          _combo = (_combo + 1).clamp(1, 6);
          if (d.type == ChDroneType.boss) { _bossPhase = false; _bossDialogue = _bossDialogues[3]; }
        }
        break;
      }
    }
    if (!hit) _combo = 1;
    if (_ammo == 0 && _totalAmmo > 0) { _isReloading = true; _reloadProgress = 0; }
    setState(() {});
  }

  void _toggleHack() {
    if (_showHack) { setState(() => _showHack = false); return; }
    List<Color> seq = List.generate(3 + _wave ~/ 2, (_) => _hackColors[_rnd.nextInt(_hackColors.length)]);
    String reward = ['Matrix Slowdown', 'Shield Recharge', 'Drone Override'][_rnd.nextInt(3)];
    _currentHack = ChHackSequence(sequence: seq, reward: reward);
    setState(() => _showHack = true);
  }

  void _hackInput(Color c) {
    if (_currentHack == null) return;
    _currentHack!.playerInput.add(c);
    int idx = _currentHack!.playerInput.length - 1;
    if (_currentHack!.playerInput[idx] != _currentHack!.sequence[idx]) {
      // Wrong — reset
      setState(() { _currentHack!.playerInput.clear(); });
      HapticFeedback.heavyImpact();
      return;
    }
    if (_currentHack!.playerInput.length == _currentHack!.sequence.length) {
      // Success!
      _applyHackReward(_currentHack!.reward);
      setState(() { _showHack = false; });
      HapticFeedback.mediumImpact();
    } else {
      setState(() {});
      HapticFeedback.lightImpact();
    }
  }

  void _applyHackReward(String reward) {
    _hackRewardMsg = ' HACK SUCCESS: $reward';
    _hackRewardTimer = 3.0;
    switch (reward) {
      case 'Matrix Slowdown':
        for (var d in _drones) d.speed *= 0.3;
        break;
      case 'Shield Recharge':
        _hasShield = true;
        _health = (_health + 30).clamp(0, 100);
        break;
      case 'Drone Override':
        // Kill all scouts
        for (int i = _drones.length - 1; i >= 0; i--) {
          if (_drones[i].type == ChDroneType.scout) { _score += 200; _drones.removeAt(i); }
        }
        break;
    }
    setState(() {});
  }

  @override
  void dispose() { _gameLoop.dispose(); super.dispose(); }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: kDarkBg,
      body: Stack(children: [
        if (_isPlaying || _isGameOver)
          Positioned.fill(child: CustomPaint(painter: ChPainter(
            drones: List.from(_drones), particles: List.from(_particles),
            crosshair: _crosshairPos, strafe: _playerStrafe, isZoomed: _isZoomed,
            damageFlash: _damageFlash, bossPhase: _bossPhase,
            bossHp: _bossHp, bossMaxHp: _bossMaxHp,
          ))),

        // HUD
        if (_isPlaying && !_isGameOver && !_showHack)
          _buildCyberHUD(),

        // Controls
        if (_isPlaying && !_isGameOver && !_showHack)
          _buildCyberControls(),

        // Boss dialogue
        if (_bossPhase && _bossDialogue.isNotEmpty && !_showHack)
          Positioned(top: 100, left: 16, right: 16, child: Container(
            padding: const EdgeInsets.all(12),
            decoration: BoxDecoration(color: Colors.black87, borderRadius: BorderRadius.circular(12),
              border: Border.all(color: kNeonGold, width: 1.5)),
            child: Text(_bossDialogue, style: TextStyle(color: kNeonGold, fontSize: 12,
              fontStyle: FontStyle.italic, shadows: [Shadow(color: kNeonGold, blurRadius: 8)])),
          )),

        // Hack reward msg
        if (_hackRewardTimer > 0)
          Positioned(top: 150, left: 0, right: 0, child: Center(child: Text(_hackRewardMsg,
            style: TextStyle(color: kNeonCyan, fontSize: 16, fontWeight: FontWeight.bold,
              shadows: [Shadow(color: kNeonCyan, blurRadius: 12)])))),

        // Hacking mini-game
        if (_showHack) _buildHackingOverlay(),

        // Start screen
        if (!_isPlaying && !_isGameOver) _buildCyberStartScreen(),

        // Game over
        if (_isGameOver) _buildCyberGameOver(),
      ]),
    );
  }

  Widget _buildCyberHUD() {
    return Stack(children: [
      Positioned(top: 44, left: 16, child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Text('WAVE $_wave', style: TextStyle(color: kNeonCyan, fontSize: 22, fontWeight: FontWeight.w900,
          shadows: [Shadow(color: kNeonCyan, blurRadius: 10)])),
        Text('SCORE: $_score', style: const TextStyle(color: Colors.white, fontSize: 16, fontWeight: FontWeight.bold)),
        Text('COMBO x$_combo', style: TextStyle(color: _combo > 2 ? kNeonMagenta : Colors.white54, fontSize: 14,
          fontWeight: FontWeight.bold, shadows: _combo > 2 ? [Shadow(color: kNeonMagenta, blurRadius: 8)] : [])),
      ])),
      Positioned(top: 44, right: 16, child: Column(crossAxisAlignment: CrossAxisAlignment.end, children: [
        Row(children: [
          if (_hasShield) Padding(padding: const EdgeInsets.only(right: 6), child: Icon(Icons.shield_rounded,
            color: kNeonCyan, size: 18, shadows: [Shadow(color: kNeonCyan, blurRadius: 12)])),
          Container(width: 100, height: 10, decoration: BoxDecoration(color: Colors.white12, borderRadius: BorderRadius.circular(5)),
            child: FractionallySizedBox(widthFactor: (_health / 100).clamp(0, 1), alignment: Alignment.centerLeft,
              child: Container(decoration: BoxDecoration(color: kNeonCyan, borderRadius: BorderRadius.circular(5),
                boxShadow: [BoxShadow(color: kNeonCyan, blurRadius: 6)])))),
        ]),
        const SizedBox(height: 6),
        _isReloading
            ? Text('RELOADING...', style: TextStyle(color: kNeonYellow, fontSize: 13))
            : Text('AMMO: $_ammo | TOTAL: $_totalAmmo', style: TextStyle(color: _ammo < 5 ? kNeonRed : Colors.white, fontSize: 13)),
        const SizedBox(height: 4),
        Text(_isZoomed ? ' SCOPE 2x' : '', style: TextStyle(color: kNeonMagenta, fontSize: 12)) ,
      ])),
    ]);
  }

  Widget _buildCyberControls() {
    return Positioned(bottom: 16, left: 16, right: 16, child: SizedBox(
      height: 200,
      child: Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [
        VirtualJoystick(size: 120, baseColor: Colors.white12, knobColor: kNeonCyan,
          onDirectionChanged: (dir) => _playerStrafe = (_playerStrafe + dir.dx * 0.022).clamp(0, 1)),
        Row(children: [
          Column(mainAxisAlignment: MainAxisAlignment.center, children: [
            ActionButton(icon: Icons.zoom_in_rounded, color: kNeonMagenta, label: _isZoomed ? 'UNZOOM' : 'SCOPE',
              onPressed: () => setState(() { _isZoomed = !_isZoomed; HapticFeedback.lightImpact(); }), size: 52),
            const SizedBox(height: 8),
            ActionButton(icon: Icons.terminal_rounded, color: kNeonCyan, label: 'HACK',
              onPressed: _toggleHack, size: 52),
          ]),
          const SizedBox(width: 12),
          VirtualJoystick(size: 120, baseColor: Colors.white12, knobColor: kNeonMagenta,
            onDirectionChanged: (dir) {
              double sens = _isZoomed ? 0.012 : 0.022;
              _crosshairPos = Offset((_crosshairPos.dx + dir.dx * sens).clamp(0.05, 0.95),
                  (_crosshairPos.dy + dir.dy * sens).clamp(0.1, 0.75));
            }),
          const SizedBox(width: 12),
