// ============================================================
// CYBER HUNT PAINTER
// ============================================================
class ChPainter extends CustomPainter {
  final List<ChDrone> drones;
  final List<ChParticle> particles;
  final Offset crosshair;
  final double strafe, damageFlash, bossHp, bossMaxHp;
  final bool isZoomed, bossPhase;

  ChPainter({required this.drones, required this.particles, required this.crosshair,
    required this.strafe, required this.isZoomed, required this.damageFlash,
    required this.bossPhase, required this.bossHp, required this.bossMaxHp});

  @override
  void paint(Canvas canvas, Size size) {
    canvas.drawRect(Rect.fromLTWH(0, 0, size.width, size.height), Paint()..color = const Color(0xFF000A16));

    // Zoom effect
    if (isZoomed) {
      canvas.save();
      canvas.translate(size.width / 2, size.height / 2);
      canvas.scale(2.0);
      canvas.translate(-size.width / 2, -size.height / 2);
    }

    final double horizonY = size.height * 0.55;
    final double viewOffsetX = (strafe - 0.5) * size.width * 0.6;
    final Offset vp = Offset(size.width / 2 - viewOffsetX, horizonY);

    // Cyberpunk grid
    double t = DateTime.now().millisecondsSinceEpoch / 1200.0;
    for (int i = -12; i <= 12; i++) {
      double sx = size.width / 2 + i * size.width / 6 - viewOffsetX * 2.5;
      canvas.drawLine(Offset(sx, size.height), vp,
          Paint()..color = kNeonCyan.withValues(alpha: 0.12)..strokeWidth = 0.8);
    }
    for (int i = 0; i < 14; i++) {
      double frac = ((i / 14.0) + t * 0.05) % 1.0;
      double y = horizonY + pow(frac, 1.5) * (size.height - horizonY);
      canvas.drawLine(Offset(0, y), Offset(size.width, y),
          Paint()..color = kNeonCyan.withValues(alpha: 0.06 + frac * 0.14)..strokeWidth = 0.5 + frac);
    }
    canvas.drawLine(Offset(0, horizonY), Offset(size.width, horizonY),
        Paint()..color = kNeonCyan.withValues(alpha: 0.6)..strokeWidth = 1.5
          ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 3));

    // Drones
    final sorted = List<ChDrone>.from(drones)..sort((a, b) => a.depth.compareTo(b.depth));
    for (var d in sorted) {
      double vOff = strafe - 0.5;
      double sx = (d.x - vOff * (1.0 - d.depth)) * size.width;
      double sy = d.y * size.height + d.depth * size.height * 0.15;
      double radius = 14 + d.depth * 60;
      double alpha = d.isDying ? d.dieTimer * 2 : 1.0;
      alpha = alpha.clamp(0.0, 1.0);

      Color c = d.type == ChDroneType.scout ? kNeonCyan : d.type == ChDroneType.hunter ? kNeonMagenta : kNeonGold;

      if (d.type == ChDroneType.boss) {
        // Boss — large hexagon with rotating rings
        Paint glow = Paint()..color = kNeonGold.withValues(alpha: alpha * 0.5)
          ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 25);
        Paint ring = Paint()..color = kNeonGold..style = PaintingStyle.stroke..strokeWidth = 3;
        canvas.drawCircle(Offset(sx, sy), radius * 1.5, glow);
        canvas.drawCircle(Offset(sx, sy), radius * 1.5, ring);
        canvas.drawCircle(Offset(sx, sy), radius * 0.8, ring..strokeWidth = 1.5);
        // HP bar
        if (bossMaxHp > 0) {
          double bw = 180.0;
          canvas.drawRect(Rect.fromLTWH(sx - bw / 2, sy - radius * 1.8, bw, 8), Paint()..color = Colors.black45);
          canvas.drawRect(Rect.fromLTWH(sx - bw / 2, sy - radius * 1.8, bw * (bossHp / bossMaxHp), 8),
              Paint()..color = kNeonGold..maskFilter = const MaskFilter.blur(BlurStyle.normal, 3));
        }
      } else {
        // Diamond-shaped drones
        Paint glow = Paint()..color = c.withValues(alpha: alpha * 0.4)..maskFilter = const MaskFilter.blur(BlurStyle.normal, 10);
        Paint fill = Paint()..color = c.withValues(alpha: alpha * 0.6);
        Paint outline = Paint()..color = c.withValues(alpha: alpha)..style = PaintingStyle.stroke..strokeWidth = 1.5;
        Path diamond = Path()
          ..moveTo(sx, sy - radius) ..lineTo(sx + radius * 0.7, sy)
          ..lineTo(sx, sy + radius * 0.6) ..lineTo(sx - radius * 0.7, sy) ..close();
        canvas.drawPath(diamond, glow);
        canvas.drawPath(diamond, fill);
        canvas.drawPath(diamond, outline);
        // HP pips
        for (int p = 0; p < d.maxHp; p++) {
          canvas.drawCircle(Offset(sx - d.maxHp * 5.0 / 2 + p * 10 + 5, sy - radius - 10), 4,
              Paint()..color = p < d.hp ? c : Colors.white12);
        }
      }
    }

    // Particles
    for (var p in particles) {
      double a = (p.life / p.maxLife).clamp(0.0, 1.0);
      canvas.drawRect(Rect.fromCenter(center: Offset(p.x * size.width, p.y * size.height),
          width: p.size * a * 1.5, height: p.size * a * 1.5),
          Paint()..color = p.color.withValues(alpha: a)
            ..maskFilter = MaskFilter.blur(BlurStyle.normal, p.size * 0.4));
    }

    if (isZoomed) canvas.restore();

    // Crosshair
    Offset center = Offset(crosshair.dx * size.width, crosshair.dy * size.height);
    Paint chp = Paint()..color = kNeonCyan..strokeWidth = 1.5..style = PaintingStyle.stroke;
    if (isZoomed) {
      canvas.drawCircle(center, 35, chp);
      canvas.drawCircle(center, 5, chp..strokeWidth = 1.0);
      canvas.drawLine(center - const Offset(55, 0), center - const Offset(8, 0), chp);
      canvas.drawLine(center + const Offset(8, 0), center + const Offset(55, 0), chp);
      canvas.drawLine(center - const Offset(0, 55), center - const Offset(0, 8), chp);
      canvas.drawLine(center + const Offset(0, 8), center + const Offset(0, 55), chp);
      // Scope vignette
      canvas.drawPath(
        Path.combine(PathOperation.difference,
          Path()..addRect(Rect.fromLTWH(0, 0, size.width, size.height)),
          Path()..addOval(Rect.fromCenter(center: center, width: 260, height: 260))),
        Paint()..color = Colors.black.withValues(alpha: 0.75),
      );
    } else {
      canvas.drawRect(Rect.fromCenter(center: center, width: 28, height: 28), chp);
      canvas.drawCircle(center, 3, Paint()..color = kNeonMagenta);
    }

    // Damage flash
    if (damageFlash > 0) {
      canvas.drawRect(Rect.fromLTWH(0, 0, size.width, size.height),
          Paint()..color = kNeonMagenta.withValues(alpha: damageFlash * 0.35));
      canvas.drawRect(Rect.fromLTWH(0, 0, size.width, size.height),
          Paint()..color = kNeonRed.withValues(alpha: damageFlash * 0.55)
            ..style = PaintingStyle.stroke..strokeWidth = 20);
    }
  }

  @override
  bool shouldRepaint(covariant CustomPainter old) => true;
}

// ============================================================
// DATA MODELS — ZOMBIE SIEGE
// ============================================================
enum ZsZombieType { walker, runner, brute, exploder }
enum ZsWeaponSelect { assaultRifle, shotgun }

class ZsZombie {
  double x, depth, speed;
  ZsZombieType type;
  int hp, maxHp;
  bool isDying = false;
  double dieTimer = 0;
  double attackCooldown = 0;
  ZsZombie({required this.x, required this.depth, required this.type,
    required this.hp, required this.speed}) : maxHp = hp;
}

class ZsParticle {
  double x, y, vx, vy, life, maxLife, size;
  Color color;
  ZsParticle({required this.x, required this.y, required this.vx, required this.vy,
    required this.life, required this.color, this.size = 3}) : maxLife = life;
}

class ZsBarricade {
  double x; // 0-1 normalized position
  int hp;
  ZsBarricade({required this.x, required this.hp});
}

class ZsSentry {
  double x;
  double fireCooldown = 0;
  ZsSentry({required this.x});
}

class ZsHealthPack {
  double x, depth;
  ZsHealthPack({required this.x, required this.depth});
}

// ============================================================
// ZOMBIE SIEGE GAME
// ============================================================
class ZombieSiegeGame extends StatefulWidget {
  const ZombieSiegeGame({Key? key}) : super(key: key);
  @override
  State<ZombieSiegeGame> createState() => _ZombieSiegeGameState();
}

class _ZombieSiegeGameState extends State<ZombieSiegeGame> with TickerProviderStateMixin {
  late AnimationController _gameLoop;

  bool _isPlaying = false, _isGameOver = false;
  bool _showSafehouse = false, _isBetweenWaves = false;
  String _difficulty = 'Medium';

  // Stats
  double _health = 100, _maxHealth = 100;
  int _score = 0, _highScore = 0, _wave = 1, _kills = 0;
  int _coins = 0;

  // Weapons
  ZsWeaponSelect _currentWeapon = ZsWeaponSelect.assaultRifle;
  int _arAmmo = 30, _arTotal = 180, _arDmg = 1;
  int _sgAmmo = 8, _sgTotal = 48, _sgDmg = 3;
  bool _isReloading = false;
  double _reloadProgress = 0;
  double _fireCooldown = 0;

  // Controls
  Offset _crosshairPos = const Offset(0.5, 0.45);
  double _playerStrafe = 0.5;
  bool _isFiring = false;

  // Entities
  final List<ZsZombie> _zombies = [];
  final List<ZsParticle> _particles = [];
  final List<ZsBarricade> _barricades = [];
  final List<ZsSentry> _sentries = [];
  final List<ZsHealthPack> _healthPacks = [];

  final Random _rnd = Random();
  double _spawnTimer = 0;
  int _zombiesToSpawn = 0;
  double _betweenWaveTimer = 0;
  double _damageFlash = 0;
  double _screenShake = 0;

  // Safehouse npc dialogue state
  int _safeTabIdx = 0; // 0=Medic, 1=Mechanic, 2=Commander
  int _medicKitCost = 60, _sentryBuildCost = 150, _barricadeCost = 80;

  // Story transmissions
  final List<String> _transmissions = const [
    ' BUNKER 99 LOG DAY 1: "The infected have overrun Sector C. We hold the south gate."',
    ' LOG DAY 4: "Dr. Kira has a working cure formula but needs more time. Hold on, Striker!"',
    ' LOG DAY 8: "Lost contact with Bravo Squad. The Brute horde is 2 clicks out."',
    ' LOG DAY 14: "Cure vials ready. We need you to survive 20 waves. You\'re our last hope."',
    ' LOG DAY 21: "The horde just broke through the east fence. FULL DEFENSE NOW!"',
  ];
  String _currentTransmission = '';
  double _transmissionTimer = 0;

  @override
  void initState() {
    super.initState();
    _loadHighScore();
    _gameLoop = AnimationController(vsync: this, duration: const Duration(seconds: 1))..repeat();
    _gameLoop.addListener(_update);
  }

  Future<void> _loadHighScore() async {
    final prefs = await SharedPreferences.getInstance();
    setState(() => _highScore = prefs.getInt('hi_score_zombie_siege') ?? 0);
  }

  Future<void> _saveHighScore() async {
    if (_score > _highScore) {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setInt('hi_score_zombie_siege', _score);
      _highScore = _score;
    }
  }

  void _startGame(String diff) {
    _difficulty = diff;
    setState(() {
      _isPlaying = true; _isGameOver = false; _showSafehouse = false; _isBetweenWaves = false;
      _health = 100; _maxHealth = 100; _score = 0; _wave = 1; _kills = 0; _coins = 100;
      _arAmmo = 30; _arTotal = 180; _arDmg = 1;
      _sgAmmo = 8; _sgTotal = 48; _sgDmg = 3;
      _isReloading = false; _fireCooldown = 0;
      _currentWeapon = ZsWeaponSelect.assaultRifle;
      _zombies.clear(); _particles.clear(); _barricades.clear(); _sentries.clear(); _healthPacks.clear();
      _crosshairPos = const Offset(0.5, 0.45);
      _playerStrafe = 0.5;
      _zombiesToSpawn = 6 + _wave * 2;
      _damageFlash = 0; _screenShake = 0;
      _currentTransmission = _transmissions[0];
      _transmissionTimer = 6.0;
    });
    HapticFeedback.mediumImpact();
  }

  void _update() {
    if (!_isPlaying || _isGameOver || _showSafehouse) return;
    const double dt = 1 / 60;

    if (_damageFlash > 0) _damageFlash -= dt * 2.5;
    if (_screenShake > 0) _screenShake -= dt * 4;
    if (_transmissionTimer > 0) _transmissionTimer -= dt;
    if (_fireCooldown > 0) _fireCooldown -= dt;

    // Auto-fire
    if (_isFiring && !_isReloading && _fireCooldown <= 0) _fire();

    // Reload
    if (_isReloading) {
      double reloadTime = _currentWeapon == ZsWeaponSelect.assaultRifle ? 2.0 : 3.0;
      _reloadProgress += dt / reloadTime;
      if (_reloadProgress >= 1.0) {
        if (_currentWeapon == ZsWeaponSelect.assaultRifle) {
          int need = 30 - _arAmmo; int from = _arTotal >= need ? need : _arTotal;
          _arAmmo += from; _arTotal -= from;
        } else {
          int need = 8 - _sgAmmo; int from = _sgTotal >= need ? need : _sgTotal;
          _sgAmmo += from; _sgTotal -= from;
        }
        _isReloading = false; _reloadProgress = 0;
      }
    }

    // Between waves
    if (_isBetweenWaves) {
      _betweenWaveTimer -= dt;
      if (_betweenWaveTimer <= 0) {
        _isBetweenWaves = false;
        _wave++;
        _zombiesToSpawn = 6 + _wave * 3;
        _coins += 80 + _wave * 10;
        _health = (_health + 15).clamp(0, _maxHealth);
        if (_wave - 1 < _transmissions.length) {
          _currentTransmission = _transmissions[(_wave - 1).clamp(0, _transmissions.length - 1)];
          _transmissionTimer = 6.0;
        }
        _showSafehouse = true; // Enter safehouse between waves
        setState(() {});
      }
      return;
    }

    // Spawn zombies
    if (_zombiesToSpawn > 0) {
      _spawnTimer += dt;
      double interval = (1.4 - _wave * 0.04).clamp(0.25, 1.4);
      if (_spawnTimer >= interval) { _spawnZombie(); _spawnTimer = 0; _zombiesToSpawn--; }
    }

    // Wave complete
    if (_zombiesToSpawn == 0 && _zombies.where((z) => !z.isDying).isEmpty) {
      _isBetweenWaves = true;
      _betweenWaveTimer = 2.0;
    }

    // Sentry auto-fire
    for (var sentry in _sentries) {
      sentry.fireCooldown -= dt;
      if (sentry.fireCooldown <= 0 && _zombies.isNotEmpty) {
        sentry.fireCooldown = 0.8;
        // Find nearest zombie to sentry
        ZsZombie? nearest;
        double nearDist = 999;
        for (var z in _zombies) {
          if (z.isDying) continue;
          double dist = (z.x - sentry.x).abs();
          if (dist < nearDist) { nearDist = dist; nearest = z; }
        }
        if (nearest != null) {
          nearest.hp -= 2;
          _spawnBloodParticle(nearest.x, 0.4 + nearest.depth * 0.45);
          if (nearest.hp <= 0) _killZombie(_zombies.indexOf(nearest));
        }
      }
    }

    // Move zombies
    for (int i = _zombies.length - 1; i >= 0; i--) {
      var z = _zombies[i];
      if (z.isDying) { z.dieTimer -= dt; if (z.dieTimer <= 0) _zombies.removeAt(i); continue; }
      z.depth += z.speed * dt;

      // Attack barricades if they're close
      for (int b = _barricades.length - 1; b >= 0; b--) {
        var bar = _barricades[b];
        if ((z.x - bar.x).abs() < 0.12 && z.depth > 0.55) {
          z.attackCooldown -= dt;
          if (z.attackCooldown <= 0) {
            bar.hp -= (z.type == ZsZombieType.brute ? 3 : 1);
            z.attackCooldown = 1.0;
            if (bar.hp <= 0) _barricades.removeAt(b);
          }
          z.depth -= z.speed * dt * 0.5; // Slowed by barricade
        }
      }

      if (z.depth >= 1.0) {
        _zombies.removeAt(i);
        double dmg = z.type == ZsZombieType.brute ? 35 : z.type == ZsZombieType.runner ? 15 : 20;
        if (_difficulty == 'Hard') dmg *= 1.4;
        if (_difficulty == 'Easy') dmg *= 0.6;
        _takeDamage(dmg);
      }
    }

    // Move health packs
    for (int i = _healthPacks.length - 1; i >= 0; i--) {
      var hp = _healthPacks[i];
      hp.depth += 0.05 * dt; // Slowly falls
      if (hp.depth > 1.0) _healthPacks.removeAt(i);
    }

    // Particles
    for (int i = _particles.length - 1; i >= 0; i--) {
      var p = _particles[i];
      p.life -= dt; p.x += p.vx * dt; p.y += p.vy * dt; p.vy += 0.4 * dt;
      if (p.life <= 0) _particles.removeAt(i);
    }

    setState(() {});
  }

  void _spawnZombie() {
    ZsZombieType type = ZsZombieType.walker;
    double rand = _rnd.nextDouble();
    if (_wave > 1 && rand > 0.65) type = ZsZombieType.runner;
    if (_wave > 3 && rand > 0.82) type = ZsZombieType.brute;
    if (_wave > 2 && rand > 0.90) type = ZsZombieType.exploder;
    double spd = type == ZsZombieType.runner ? 0.18 : type == ZsZombieType.brute ? 0.05 : type == ZsZombieType.exploder ? 0.12 : 0.08;
    spd += _wave * 0.006;
    if (_difficulty == 'Easy') spd *= 0.65;
    if (_difficulty == 'Hard') spd *= 1.5;
    int hp = type == ZsZombieType.walker ? 1 : type == ZsZombieType.runner ? 1 : type == ZsZombieType.brute ? 4 + _wave : 1;
    _zombies.add(ZsZombie(
      x: _rnd.nextDouble() * 0.75 + 0.12,
      depth: 0.0, type: type, hp: hp, speed: spd,
    ));
  }

  void _takeDamage(double amt) {
    _health -= amt;
    _damageFlash = 1.0;
    _screenShake = 1.0;
    HapticFeedback.heavyImpact();
    if (_health <= 0) {
      _health = 0; _isGameOver = true; _isPlaying = false; _saveHighScore();
    }
    setState(() {});
  }

  void _fire() {
    int ammo = _currentWeapon == ZsWeaponSelect.assaultRifle ? _arAmmo : _sgAmmo;
    if (_isReloading || ammo <= 0) {
      if (ammo <= 0 && !_isReloading) _reload();
      return;
    }
    if (_currentWeapon == ZsWeaponSelect.assaultRifle) {
      _arAmmo--;
      _fireCooldown = 0.12;
    } else {
      _sgAmmo--;
      _fireCooldown = 0.55;
    }
    HapticFeedback.lightImpact();

    int pellets = _currentWeapon == ZsWeaponSelect.shotgun ? 5 : 1;
    double hitRadius = _currentWeapon == ZsWeaponSelect.shotgun ? 0.14 : 0.06;
    int dmg = _currentWeapon == ZsWeaponSelect.assaultRifle ? _arDmg : _sgDmg;

    for (int pellet = 0; pellet < pellets; pellet++) {
      double aimX = _crosshairPos.dx + (_rnd.nextDouble() - 0.5) * hitRadius * 2;
      double aimY = _crosshairPos.dy + (_rnd.nextDouble() - 0.5) * hitRadius;

      for (int i = _zombies.length - 1; i >= 0; i--) {
        if (_zombies[i].isDying) continue;
        var z = _zombies[i];
        double vOff = _playerStrafe - 0.5;
        double sx = z.x - vOff * (1.0 - z.depth);
        double sy = 0.42 + z.depth * 0.42;
        double esz = hitRadius + z.depth * 0.1;
        double dx = sx - aimX, dy = sy - aimY;
        if (sqrt(dx * dx + dy * dy) < esz) {
          z.hp -= dmg;
          _spawnBloodParticle(sx, sy);
          if (z.hp <= 0) _killZombie(i);
          if (_currentWeapon != ZsWeaponSelect.shotgun) break;
        }
      }
    }

    // Auto reload when empty
    if (_currentWeapon == ZsWeaponSelect.assaultRifle && _arAmmo == 0 && _arTotal > 0) _reload();
    if (_currentWeapon == ZsWeaponSelect.shotgun && _sgAmmo == 0 && _sgTotal > 0) _reload();
    setState(() {});
  }

  void _killZombie(int idx) {
    if (idx < 0 || idx >= _zombies.length) return;
    var z = _zombies[idx];
    z.isDying = true; z.dieTimer = 0.5;
    int pts = z.type == ZsZombieType.walker ? 50 : z.type == ZsZombieType.runner ? 100 : z.type == ZsZombieType.brute ? 400 : 200;
    _score += pts; _kills++; _coins += pts ~/ 10;
    // Exploder: area damage to nearby zombies
    if (z.type == ZsZombieType.exploder) {
      _spawnExplosionParticles(z.x, 0.42 + z.depth * 0.42);
      for (int j = _zombies.length - 1; j >= 0; j--) {
        if (j == idx || _zombies[j].isDying) continue;
        double dist = (z.x - _zombies[j].x).abs();
        if (dist < 0.2) { _zombies[j].hp -= 3; if (_zombies[j].hp <= 0) _killZombie(j); }
      }
      _screenShake = 1.0;
    }
    // Health pack drop
    if (_rnd.nextDouble() < 0.12) {
      _healthPacks.add(ZsHealthPack(x: z.x, depth: z.depth));
    }
    HapticFeedback.mediumImpact();
  }

  void _reload() {
    if (_isReloading) return;
    int ammo = _currentWeapon == ZsWeaponSelect.assaultRifle ? _arAmmo : _sgAmmo;
    int clip = _currentWeapon == ZsWeaponSelect.assaultRifle ? 30 : 8;
    int total = _currentWeapon == ZsWeaponSelect.assaultRifle ? _arTotal : _sgTotal;
    if (ammo >= clip || total <= 0) return;
    _isReloading = true; _reloadProgress = 0;
    HapticFeedback.mediumImpact();
  }

  void _switchWeapon() {
    if (_isReloading) return;
    setState(() {
      _currentWeapon = _currentWeapon == ZsWeaponSelect.assaultRifle ? ZsWeaponSelect.shotgun : ZsWeaponSelect.assaultRifle;
      _isReloading = false;
    });
    HapticFeedback.selectionClick();
  }

  void _tryPickupHealthPack() {
    double cx = _crosshairPos.dx;
    for (int i = _healthPacks.length - 1; i >= 0; i--) {
      var hp = _healthPacks[i];
      if ((hp.x - cx).abs() < 0.12) {
        _health = (_health + 25).clamp(0, _maxHealth);
        _healthPacks.removeAt(i);
        HapticFeedback.lightImpact();
        break;
      }
    }
  }

  void _spawnBloodParticle(double x, double y) {
    for (int i = 0; i < 8; i++) {
      double ang = _rnd.nextDouble() * pi;
      double spd = 0.15 + _rnd.nextDouble() * 0.35;
      _particles.add(ZsParticle(x: x, y: y, vx: cos(ang) * spd, vy: sin(ang) * spd - 0.3,
          life: 0.3 + _rnd.nextDouble() * 0.4, color: Colors.red.shade900, size: 2 + _rnd.nextDouble() * 3));
    }
  }

  void _spawnExplosionParticles(double x, double y) {
    for (int i = 0; i < 25; i++) {
      double ang = _rnd.nextDouble() * 2 * pi;
      double spd = 0.3 + _rnd.nextDouble() * 0.8;
      _particles.add(ZsParticle(x: x, y: y, vx: cos(ang) * spd, vy: sin(ang) * spd - 0.5,
          life: 0.5 + _rnd.nextDouble() * 0.7, color: _rnd.nextBool() ? kNeonOrange : kNeonYellow, size: 4 + _rnd.nextDouble() * 8));
    }
  }

  @override
  void dispose() { _gameLoop.dispose(); super.dispose(); }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: kDarkBg,
      body: Stack(children: [
        if (_isPlaying || _isGameOver)
          Positioned.fill(child: CustomPaint(painter: ZsPainter(
            zombies: List.from(_zombies), particles: List.from(_particles),
            barricades: List.from(_barricades), sentries: List.from(_sentries),
            healthPacks: List.from(_healthPacks),
            crosshair: _crosshairPos, strafe: _playerStrafe,
            damageFlash: _damageFlash, screenShake: _screenShake,
            currentWeapon: _currentWeapon,
          ))),

        if (_isPlaying && !_isGameOver && !_showSafehouse)
          _buildZombieHUD(),

        if (_isPlaying && !_isGameOver && !_showSafehouse)
          _buildZombieControls(),

        // Transmission banner
        if (_transmissionTimer > 0 && !_showSafehouse)
          Positioned(top: 130, left: 16, right: 16, child: Container(
            padding: const EdgeInsets.all(10),
            decoration: BoxDecoration(color: Colors.black87, borderRadius: BorderRadius.circular(10),
              border: Border.all(color: Colors.green.shade800)),
            child: Text(_currentTransmission, style: TextStyle(color: Colors.green.shade400, fontSize: 11)),
          )),

        // Between waves
        if (_isBetweenWaves && !_showSafehouse)
          Center(child: Text('WAVE $_wave CLEARED!\nEntering Safehouse...', textAlign: TextAlign.center,
            style: TextStyle(color: Colors.green, fontSize: 30, fontWeight: FontWeight.w900,
              shadows: [Shadow(color: Colors.green, blurRadius: 20)]))),

        // Safehouse UI
        if (_showSafehouse) _buildSafehouseUI(),

        // Start screen
        if (!_isPlaying && !_isGameOver) _buildZombieStartScreen(),

        // Game over
        if (_isGameOver) _buildZombieGameOver(),
      ]),
    );
  }

  Widget _buildZombieHUD() {
    int ammo = _currentWeapon == ZsWeaponSelect.assaultRifle ? _arAmmo : _sgAmmo;
    int total = _currentWeapon == ZsWeaponSelect.assaultRifle ? _arTotal : _sgTotal;
    int clip = _currentWeapon == ZsWeaponSelect.assaultRifle ? 30 : 8;
    String wName = _currentWeapon == ZsWeaponSelect.assaultRifle ? 'ASSAULT RIFLE' : 'SHOTGUN';
    Color wColor = _currentWeapon == ZsWeaponSelect.assaultRifle ? kNeonGreen : kNeonOrange;

    return Stack(children: [
      Positioned(top: 44, left: 16, child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Text('WAVE $_wave', style: TextStyle(color: Colors.green, fontSize: 22, fontWeight: FontWeight.w900,
          shadows: [Shadow(color: Colors.green, blurRadius: 10)])),
        Text('SCORE: $_score', style: const TextStyle(color: Colors.white, fontSize: 16, fontWeight: FontWeight.bold)),
        Text('KILLS: $_kills', style: const TextStyle(color: Colors.white60, fontSize: 13)),
        Text('COINS: $_coins', style: TextStyle(color: kNeonGold, fontSize: 13)),
      ])),
      Positioned(top: 44, right: 16, child: Column(crossAxisAlignment: CrossAxisAlignment.end, children: [
        Row(children: [
          Icon(Icons.favorite, color: Colors.redAccent, size: 16),
          const SizedBox(width: 6),
          Container(width: 100, height: 10, decoration: BoxDecoration(color: Colors.white12, borderRadius: BorderRadius.circular(5)),
            child: FractionallySizedBox(widthFactor: (_health / _maxHealth).clamp(0, 1), alignment: Alignment.centerLeft,
              child: Container(decoration: BoxDecoration(color: Colors.redAccent, borderRadius: BorderRadius.circular(5),
                boxShadow: [const BoxShadow(color: Colors.red, blurRadius: 6)])))),
        ]),
        const SizedBox(height: 6),
        Text(wName, style: TextStyle(color: wColor, fontSize: 12, fontWeight: FontWeight.bold)),
        _isReloading
            ? Text('RELOADING...', style: TextStyle(color: kNeonYellow, fontSize: 13))
            : Text('$ammo/$clip | TOTAL: $total', style: TextStyle(color: ammo < 3 ? kNeonRed : Colors.white, fontSize: 13)),
        if (_sentries.isNotEmpty) Text('SENTRIES: ${_sentries.length}', style: TextStyle(color: kNeonCyan, fontSize: 12)),
        if (_barricades.isNotEmpty) Text('BARRICADES: ${_barricades.length}', style: TextStyle(color: Colors.brown, fontSize: 12)),
      ])),
    ]);
  }

  Widget _buildZombieControls() {
    return Positioned(bottom: 16, left: 16, right: 16, child: SizedBox(
      height: 200,
      child: Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [
        VirtualJoystick(size: 120, baseColor: Colors.white12, knobColor: Colors.green,
          onDirectionChanged: (dir) => _playerStrafe = (_playerStrafe + dir.dx * 0.022).clamp(0, 1)),
        Row(children: [
          Column(mainAxisAlignment: MainAxisAlignment.center, children: [
            ActionButton(icon: Icons.refresh, color: kNeonYellow, label: 'RELOAD', onPressed: _reload, size: 50),
            const SizedBox(height: 8),
            ActionButton(icon: Icons.swap_horiz_rounded, color: kNeonOrange, label: 'SWITCH', onPressed: _switchWeapon, size: 50),
          ]),
          const SizedBox(width: 12),
          VirtualJoystick(size: 120, baseColor: Colors.white12, knobColor: Colors.redAccent,
            onDirectionChanged: (dir) {
              _crosshairPos = Offset((_crosshairPos.dx + dir.dx * 0.022).clamp(0.05, 0.95),
                  (_crosshairPos.dy + dir.dy * 0.022).clamp(0.15, 0.78));
            }),
          const SizedBox(width: 12),
          Column(mainAxisAlignment: MainAxisAlignment.center, children: [
            ActionButton(icon: Icons.gps_fixed, color: Colors.redAccent, label: 'FIRE',
              onPressStart: () { _isFiring = true; _fire(); },
              onPressEnd: () => _isFiring = false, onPressed: _fire, size: 80),
            const SizedBox(height: 8),
            ActionButton(icon: Icons.medical_services_rounded, color: Colors.pink, label: 'PICKUP',
              onPressed: _tryPickupHealthPack, size: 44),
          ]),
        ]),
      ]),
    ));
  }

  Widget _buildSafehouseUI() {
    return Container(
      color: Colors.black.withValues(alpha: 0.95),
      child: SafeArea(child: Column(children: [
        Container(padding: const EdgeInsets.all(14), color: Colors.green.shade900.withValues(alpha: 0.6),
          child: Row(children: [
            const Icon(Icons.house_rounded, color: Colors.green),
            const SizedBox(width: 10),
            Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Text('BUNKER 99 SAFEHOUSE', style: TextStyle(color: Colors.green.shade400, fontWeight: FontWeight.w900, fontSize: 16, letterSpacing: 2)),
              Text('WAVE ${_wave + 1} INCOMING |  COINS: $_coins', style: const TextStyle(color: Colors.white60, fontSize: 12)),
            ]),
          ])),
        // NPC Tabs
        Row(children: [
          _safeTab(' MEDIC', 0),
          _safeTab(' MECHANIC', 1),
          _safeTab(' COMMANDER', 2),
        ]),
        Expanded(child: SingleChildScrollView(padding: const EdgeInsets.all(16), child: _buildSafeTab())),
        Padding(padding: const EdgeInsets.all(12), child: ElevatedButton.icon(
          style: ElevatedButton.styleFrom(backgroundColor: Colors.red.shade900,
            padding: const EdgeInsets.symmetric(horizontal: 32, vertical: 14)),
          icon: const Icon(Icons.exit_to_app_rounded, color: Colors.white),
          label: const Text('EXIT SAFEHOUSE', style: TextStyle(color: Colors.white, fontWeight: FontWeight.bold, fontSize: 16)),
          onPressed: () => setState(() {
            _showSafehouse = false;
            _wave++;
            _zombiesToSpawn = 6 + _wave * 3;
            _spawnTimer = 0;
          }),
        )),
      ])),
    );
  }

  Widget _safeTab(String label, int idx) {
    bool sel = _safeTabIdx == idx;
    return Expanded(child: GestureDetector(
      onTap: () => setState(() => _safeTabIdx = idx),
      child: Container(padding: const EdgeInsets.all(10),
        decoration: BoxDecoration(
          color: sel ? Colors.green.shade900.withValues(alpha: 0.5) : Colors.transparent,
          border: Border(bottom: BorderSide(color: sel ? Colors.green : Colors.transparent, width: 2)),
        ),
        child: Text(label, textAlign: TextAlign.center, style: TextStyle(
          color: sel ? Colors.green : Colors.white54, fontWeight: FontWeight.bold, fontSize: 13)),
      ),
    ));
  }

  Widget _buildSafeTab() {
    switch (_safeTabIdx) {
      case 0: // Medic
        return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Text('DR. KIRA', style: TextStyle(color: Colors.green.shade400, fontWeight: FontWeight.bold, fontSize: 18)),
          const SizedBox(height: 6),
          Text('"Stay alive out there. I\'m working on the cure..."', style: TextStyle(color: Colors.green.shade700, fontStyle: FontStyle.italic)),
          const SizedBox(height: 16),
          _sfBtn(' Medkit (+30 HP)', medicKitCost: _medicKitCost, onBuy: () {
            if (_coins >= _medicKitCost) { setState(() { _coins -= _medicKitCost; _health = (_health + 30).clamp(0, _maxHealth); _medicKitCost += 20; }); }
          }),
          _sfBtn(' Max Health Upgrade (+20 Max HP)', medicKitCost: 150, onBuy: () {
            if (_coins >= 150) { setState(() { _coins -= 150; _maxHealth += 20; _health = _maxHealth; }); }
          }),
          _sfBtn(' Adrenaline Shot (Fill all ammo)', medicKitCost: 200, onBuy: () {
            if (_coins >= 200) { setState(() { _coins -= 200; _arAmmo = 30; _arTotal = 180; _sgAmmo = 8; _sgTotal = 48; }); }
          }),
        ]);

      case 1: // Mechanic
        return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Text('MECH KOVACS', style: TextStyle(color: Colors.orange.shade400, fontWeight: FontWeight.bold, fontSize: 18)),
          const SizedBox(height: 6),
          Text('"I can boost your firepower or build defense hardware."', style: TextStyle(color: Colors.orange.shade800, fontStyle: FontStyle.italic)),
          const SizedBox(height: 16),
          _sfBtn(' AR Damage Upgrade (+1 dmg)', medicKitCost: _weaponUpCost(), onBuy: () {
            if (_coins >= _weaponUpCost()) { setState(() { _coins -= _weaponUpCost(); _arDmg += 1; }); }
          }),
          _sfBtn(' Shotgun Damage Upgrade (+2 dmg)', medicKitCost: _weaponUpCost() + 30, onBuy: () {
            int cost = _weaponUpCost() + 30;
            if (_coins >= cost) { setState(() { _coins -= cost; _sgDmg += 2; }); }
          }),
          _sfBtn(' Build Auto-Sentry Turret', medicKitCost: _sentryBuildCost, onBuy: () {
            if (_coins >= _sentryBuildCost && _sentries.length < 4) {
              setState(() { _coins -= _sentryBuildCost; _sentries.add(ZsSentry(x: 0.2 + _sentries.length * 0.2)); _sentryBuildCost += 50; });
            }
          }),
          if (_sentries.isNotEmpty)
            Text('Sentries: ${_sentries.length}/4', style: TextStyle(color: kNeonCyan, fontSize: 13)),
        ]);

      case 2: // Commander
        return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          Text('COMMANDER REX', style: TextStyle(color: Colors.blue.shade400, fontWeight: FontWeight.bold, fontSize: 18)),
          const SizedBox(height: 6),
          Text('"We have to hold the perimeter. Fortify everything!"', style: TextStyle(color: Colors.blue.shade800, fontStyle: FontStyle.italic)),
          const SizedBox(height: 16),
          _sfBtn(' Build Barricade', medicKitCost: _barricadeCost, onBuy: () {
            if (_coins >= _barricadeCost && _barricades.length < 5) {
              setState(() { _coins -= _barricadeCost; _barricades.add(ZsBarricade(x: 0.1 + _barricades.length * 0.18, hp: 8)); _barricadeCost += 30; });
            }
          }),
          _sfBtn(' Repair Barricades (restore HP)', medicKitCost: 60, onBuy: () {
            if (_coins >= 60) { setState(() { _coins -= 60; for (var b in _barricades) b.hp = 8; }); }
          }),
          _sfBtn(' Call Reinforcements (kill 3 zombies)', medicKitCost: 120, onBuy: () {
            if (_coins >= 120) {
              int killed = 0;
              setState(() {
                _coins -= 120;
                for (int i = _zombies.length - 1; i >= 0 && killed < 3; i--) {
                  _zombies.removeAt(i); killed++;
                }
              });
            }
          }),
          if (_barricades.isNotEmpty)
            Text('Barricades: ${_barricades.length}/5 (HP: ${_barricades.map((b) => b.hp).join(', ')})',
              style: TextStyle(color: Colors.brown.shade300, fontSize: 12)),
        ]);

      default: return const SizedBox();
    }
  }

  int _weaponUpCost() => 80 + _arDmg * 20;

  Widget _sfBtn(String label, {required int medicKitCost, required VoidCallback onBuy}) {
    bool canAfford = _coins >= medicKitCost;
    return Container(margin: const EdgeInsets.only(bottom: 10), child: ElevatedButton(
      style: ElevatedButton.styleFrom(
        backgroundColor: canAfford ? Colors.green.shade900.withValues(alpha: 0.4) : Colors.white10,
        side: BorderSide(color: canAfford ? Colors.green.shade700 : Colors.white12),
        padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
        alignment: Alignment.centerLeft,
      ),
      onPressed: canAfford ? onBuy : null,
      child: Row(children: [
        Expanded(child: Text(label, style: const TextStyle(color: Colors.white, fontSize: 13))),
        Text('$medicKitCost ', style: TextStyle(color: canAfford ? kNeonGold : Colors.white38, fontWeight: FontWeight.bold)),
      ]),
    ));
  }

  Widget _buildZombieStartScreen() {
    return Center(child: Container(
      margin: const EdgeInsets.all(24), padding: const EdgeInsets.all(28),
      decoration: BoxDecoration(color: Colors.black87, border: Border.all(color: Colors.green, width: 2),
        borderRadius: BorderRadius.circular(24), boxShadow: [BoxShadow(color: Colors.green.withValues(alpha: 0.4), blurRadius: 40)]),
      child: Column(mainAxisSize: MainAxisSize.min, children: [
        Text('ZOMBIE SIEGE', style: TextStyle(color: Colors.green, fontSize: 32, fontWeight: FontWeight.w900,
          letterSpacing: 4, shadows: [Shadow(color: Colors.green, blurRadius: 20)])),
        const SizedBox(height: 6),
        Text('BUNKER 99 SURVIVAL', style: TextStyle(color: kNeonLime, fontSize: 14, letterSpacing: 3)),
        const SizedBox(height: 8),
        const Text('The infected have overrun the city. Hold Bunker 99 until the cure is ready!',
          style: TextStyle(color: Colors.white60, fontSize: 12), textAlign: TextAlign.center),
        const SizedBox(height: 16),
        Text('HIGH SCORE: $_highScore', style: TextStyle(color: kNeonGold, fontSize: 16, fontWeight: FontWeight.bold)),
        const SizedBox(height: 20),
        const Text('SELECT DIFFICULTY', style: TextStyle(color: Colors.white54, fontSize: 12, letterSpacing: 3)),
        const SizedBox(height: 10),
        Row(mainAxisSize: MainAxisSize.min, children: [
          _diffBtn('EASY', Colors.green, () => _startGame('Easy')),
          const SizedBox(width: 10),
          _diffBtn('MEDIUM', kNeonOrange, () => _startGame('Medium')),
          const SizedBox(width: 10),
          _diffBtn('HARD', kNeonRed, () => _startGame('Hard')),
        ]),
        const SizedBox(height: 20),
        const OnlinePlayersPanel(gameName: 'Zombie Siege'),
        const SizedBox(height: 10),
        TextButton(onPressed: () => Navigator.pop(context),
          child: const Text('◀ BACK', style: TextStyle(color: Colors.white38))),
      ]),
    ));
  }

  Widget _buildZombieGameOver() {
    bool newRecord = _score > _highScore && _score > 0;
    return Center(child: Container(
      margin: const EdgeInsets.all(24), padding: const EdgeInsets.all(28),
      decoration: BoxDecoration(color: Colors.black87, border: Border.all(color: Colors.red.shade900, width: 2),
        borderRadius: BorderRadius.circular(24), boxShadow: [BoxShadow(color: Colors.red.withValues(alpha: 0.5), blurRadius: 40)]),
      child: Column(mainAxisSize: MainAxisSize.min, children: [
        const Text('OVERRUN', style: TextStyle(color: Colors.red, fontSize: 36, fontWeight: FontWeight.w900, letterSpacing: 4)),
        const SizedBox(height: 16),
        Text('SCORE: $_score', style: const TextStyle(color: Colors.white, fontSize: 24, fontWeight: FontWeight.bold)),
        Text('WAVE REACHED: $_wave', style: const TextStyle(color: Colors.white70, fontSize: 16)),
        Text('KILLS: $_kills', style: const TextStyle(color: Colors.white54, fontSize: 14)),
        if (newRecord) Text(' NEW HIGH SCORE!', style: TextStyle(color: kNeonGold, fontSize: 18,
          fontWeight: FontWeight.w900, shadows: [Shadow(color: kNeonGold, blurRadius: 15)])),
        const SizedBox(height: 24),
        Row(mainAxisSize: MainAxisSize.min, children: [
          ElevatedButton(style: ElevatedButton.styleFrom(backgroundColor: Colors.red.shade900),
            onPressed: () => _startGame(_difficulty),
            child: const Text('RETRY', style: TextStyle(color: Colors.white, fontWeight: FontWeight.bold))),
          const SizedBox(width: 12),
          OutlinedButton(style: OutlinedButton.styleFrom(side: const BorderSide(color: Colors.white30)),
            onPressed: () => setState(() { _isGameOver = false; _isPlaying = false; }),
            child: const Text('MENU', style: TextStyle(color: Colors.white54))),
        ]),
      ]),
    ));
  }

  Widget _diffBtn(String label, Color color, VoidCallback onTap) {
    return ElevatedButton(
      style: ElevatedButton.styleFrom(backgroundColor: color.withValues(alpha: 0.2),
        side: BorderSide(color: color), padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 10)),
      onPressed: onTap,
      child: Text(label, style: TextStyle(color: color, fontWeight: FontWeight.bold)),
    );
  }
}

// ============================================================
// ZOMBIE SIEGE PAINTER
// ============================================================
class ZsPainter extends CustomPainter {
  final List<ZsZombie> zombies;
  final List<ZsParticle> particles;
  final List<ZsBarricade> barricades;
  final List<ZsSentry> sentries;
  final List<ZsHealthPack> healthPacks;
  final Offset crosshair;
  final double strafe, damageFlash, screenShake;
  final ZsWeaponSelect currentWeapon;

  ZsPainter({required this.zombies, required this.particles, required this.barricades,
    required this.sentries, required this.healthPacks, required this.crosshair,
    required this.strafe, required this.damageFlash, required this.screenShake,
    required this.currentWeapon});

  @override
  void paint(Canvas canvas, Size size) {
    final rnd = Random();
    if (screenShake > 0) {
      canvas.save();
      canvas.translate((rnd.nextDouble() - 0.5) * screenShake * 10, (rnd.nextDouble() - 0.5) * screenShake * 6);
    }

    // Background — dark zombie fog
    canvas.drawRect(Rect.fromLTWH(0, 0, size.width, size.height), Paint()..color = const Color(0xFF050805));

    // Blood red fog at horizon
    final fogPaint = Paint()..shader = RadialGradient(
      center: Alignment.topCenter, radius: 1.5,
      colors: [Colors.red.withValues(alpha: 0.12), Colors.transparent],
    ).createShader(Rect.fromLTWH(0, 0, size.width, size.height * 0.6));
    canvas.drawRect(Rect.fromLTWH(0, 0, size.width, size.height * 0.6), fogPaint);

    final double horizonY = size.height * 0.44;
    final double viewOffsetX = (strafe - 0.5) * size.width * 0.7;
    final Offset vp = Offset(size.width / 2 - viewOffsetX, horizonY);

    // Ground
    canvas.drawRect(Rect.fromLTRB(0, horizonY, size.width, size.height),
        Paint()..color = const Color(0xFF0A0A06));

    // Ground cracks / blood puddles
    final rndStatic = Random(7);
    for (int i = 0; i < 8; i++) {
      double px = rndStatic.nextDouble() * size.width;
      double py = horizonY + 40 + rndStatic.nextDouble() * (size.height - horizonY - 60);
      canvas.drawCircle(Offset(px, py), 8 + rndStatic.nextDouble() * 20, Paint()..color = Colors.red.shade900.withValues(alpha: 0.35));
    }

    // Grid perspective
    final gridPaint = Paint()..color = Colors.green.withValues(alpha: 0.1)..strokeWidth = 0.7;
    for (int i = -7; i <= 7; i++) {
      double sx = size.width / 2 + i * size.width / 4 - viewOffsetX * 2;
      canvas.drawLine(Offset(sx, size.height), vp, gridPaint);
    }
    for (int i = 1; i <= 10; i++) {
      double t = i / 10.0;
      double y = horizonY + pow(t, 1.6) * (size.height - horizonY);
      canvas.drawLine(Offset(0, y), Offset(size.width, y), gridPaint..color = Colors.green.withValues(alpha: 0.05 + t * 0.1));
    }

    // Barricades
    for (var b in barricades) {
      double bx = (b.x - (strafe - 0.5) * 0.5) * size.width;
      double by = horizonY + (size.height - horizonY) * 0.55;
      double bw = 60; double bh = 35;
      double healthFrac = b.hp / 8.0;
      Paint barPaint = Paint()..color = Color.lerp(Colors.red.shade900, Colors.brown.shade800, healthFrac)!;
      canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(bx - bw / 2, by, bw, bh), const Radius.circular(4)), barPaint);
      // Planks
      for (int p = 0; p < 4; p++) {
        canvas.drawLine(Offset(bx - bw / 2 + p * bw / 4 + 4, by + 4),
          Offset(bx - bw / 2 + p * bw / 4 + 4, by + bh - 4),
          Paint()..color = Colors.brown.shade400..strokeWidth = 2);
      }
    }

    // Sentry turrets
    for (var s in sentries) {
      double sx = (s.x - (strafe - 0.5) * 0.3) * size.width;
      double sy = horizonY + (size.height - horizonY) * 0.65;
      canvas.drawRect(Rect.fromCenter(center: Offset(sx, sy), width: 30, height: 20),
          Paint()..color = const Color(0xFF334433));
      canvas.drawLine(Offset(sx, sy - 10), Offset(sx, sy - 30),
          Paint()..color = kNeonCyan..strokeWidth = 4..maskFilter = const MaskFilter.blur(BlurStyle.normal, 3));
      canvas.drawCircle(Offset(sx, sy), 4, Paint()..color = kNeonCyan..maskFilter = const MaskFilter.blur(BlurStyle.normal, 6));
    }

    // Health packs on ground
    for (var hp in healthPacks) {
      double vOff = strafe - 0.5;
      double hx = (hp.x - vOff * (1 - hp.depth)) * size.width;
      double hy = horizonY + hp.depth * (size.height - horizonY);
      canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromCenter(center: Offset(hx, hy), width: 20, height: 20), const Radius.circular(4)),
          Paint()..color = Colors.red.shade700);
      canvas.drawLine(Offset(hx - 5, hy), Offset(hx + 5, hy), Paint()..color = Colors.white..strokeWidth = 3);
      canvas.drawLine(Offset(hx, hy - 5), Offset(hx, hy + 5), Paint()..color = Colors.white..strokeWidth = 3);
    }

    // Zombies
    final sorted = List<ZsZombie>.from(zombies)..sort((a, b) => a.depth.compareTo(b.depth));
    for (var z in sorted) {
      double vOff = strafe - 0.5;
      double sx = (z.x - vOff * (1.0 - z.depth)) * size.width;
      double sy = horizonY + z.depth * (size.height - horizonY);
      double radius = 10 + z.depth * 50;
      double alpha = z.isDying ? (z.dieTimer * 2.5).clamp(0, 1) : 1.0;

      Color bodyColor = z.type == ZsZombieType.walker ? const Color(0xFF2E6B2E) :
          z.type == ZsZombieType.runner ? const Color(0xFF8B8B00) :
          z.type == ZsZombieType.brute ? Colors.red.shade900 : Colors.orange.shade800;

      Paint glow = Paint()..color = bodyColor.withValues(alpha: alpha * 0.4)..maskFilter = const MaskFilter.blur(BlurStyle.normal, 12);
      Paint fill = Paint()..color = bodyColor.withValues(alpha: alpha * 0.85);

      if (z.type == ZsZombieType.brute) {
        // Big square brute
        canvas.drawRect(Rect.fromCenter(center: Offset(sx, sy - radius * 0.8), width: radius * 1.8, height: radius * 2.2), glow);
        canvas.drawRect(Rect.fromCenter(center: Offset(sx, sy - radius * 0.8), width: radius * 1.6, height: radius * 2.0), fill);
        // Head
        canvas.drawRect(Rect.fromCenter(center: Offset(sx, sy - radius * 2.0), width: radius * 1.2, height: radius * 0.8), fill);
      } else {
        // Standard zombie figure
        canvas.drawCircle(Offset(sx, sy - radius * 1.25), radius * 0.4, glow); // head glow
        canvas.drawCircle(Offset(sx, sy - radius * 1.25), radius * 0.35, fill); // head
        canvas.drawRect(Rect.fromCenter(center: Offset(sx, sy - radius * 0.6), width: radius * 0.7, height: radius * 0.9), fill); // body
        // Arms (spread out like zombie)
        canvas.drawLine(Offset(sx - radius * 0.35, sy - radius * 0.6), Offset(sx - radius, sy - radius * 0.4),
            Paint()..color = bodyColor.withValues(alpha: alpha)..strokeWidth = radius * 0.2..strokeCap = StrokeCap.round);
        canvas.drawLine(Offset(sx + radius * 0.35, sy - radius * 0.6), Offset(sx + radius, sy - radius * 0.4),
            Paint()..color = bodyColor.withValues(alpha: alpha)..strokeWidth = radius * 0.2..strokeCap = StrokeCap.round);
      }

      // Exploder — glowing orange outline
      if (z.type == ZsZombieType.exploder) {
        double pulse = (sin(DateTime.now().millisecondsSinceEpoch / 200.0) + 1) / 2;
        canvas.drawCircle(Offset(sx, sy - radius * 0.8), radius * 0.6,
            Paint()..color = kNeonOrange.withValues(alpha: alpha * 0.3 * (0.5 + pulse * 0.5))
              ..style = PaintingStyle.stroke..strokeWidth = 3
              ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 8));
      }

      // HP bar
      if (!z.isDying && z.maxHp > 1) {
        double bw = radius * 1.6;
        canvas.drawRect(Rect.fromLTWH(sx - bw / 2, sy - radius * 2.0, bw, 4), Paint()..color = Colors.black45);
        canvas.drawRect(Rect.fromLTWH(sx - bw / 2, sy - radius * 2.0, bw * z.hp / z.maxHp, 4),
            Paint()..color = Colors.green);
      }
    }

    // Particles
    for (var p in particles) {
      double a = (p.life / p.maxLife).clamp(0.0, 1.0);
      canvas.drawCircle(Offset(p.x * size.width, p.y * size.height), p.size * a,
          Paint()..color = p.color.withValues(alpha: a)..maskFilter = MaskFilter.blur(BlurStyle.normal, p.size * 0.3));
    }

    // Crosshair based on weapon
    _drawZsCrosshair(canvas, size);

    // Damage vignette
    if (damageFlash > 0) {
      canvas.drawRect(Rect.fromLTWH(0, 0, size.width, size.height),
          Paint()..color = Colors.red.withValues(alpha: damageFlash * 0.42));
      canvas.drawRect(Rect.fromLTWH(0, 0, size.width, size.height),
          Paint()..color = Colors.red.withValues(alpha: damageFlash * 0.65)
            ..style = PaintingStyle.stroke..strokeWidth = 24);
    }

    if (screenShake > 0) canvas.restore();
  }

  void _drawZsCrosshair(Canvas canvas, Size size) {
    Offset center = Offset(crosshair.dx * size.width, crosshair.dy * size.height);
    bool isShotgun = currentWeapon == ZsWeaponSelect.shotgun;
    Paint p = Paint()..color = isShotgun ? kNeonOrange : kNeonGreen..strokeWidth = 1.5..style = PaintingStyle.stroke;
    if (isShotgun) {
      canvas.drawCircle(center, 22, p);
      canvas.drawCircle(center, 10, p..strokeWidth = 1.0);
      for (int i = 0; i < 4; i++) {
        double a = i * pi / 2;
        canvas.drawLine(center + Offset(cos(a) * 25, sin(a) * 25), center + Offset(cos(a) * 32, sin(a) * 32), p);
      }
    } else {
      canvas.drawCircle(center, 14, p);
      canvas.drawLine(center - const Offset(20, 0), center - const Offset(6, 0), p);
      canvas.drawLine(center + const Offset(6, 0), center + const Offset(20, 0), p);
      canvas.drawLine(center - const Offset(0, 20), center - const Offset(0, 6), p);
      canvas.drawLine(center + const Offset(0, 6), center + const Offset(0, 20), p);
    }
    canvas.drawCircle(center, 2.5, Paint()..color = Colors.white);
  }

  @override
  bool shouldRepaint(covariant CustomPainter old) => true;
}

